// BEGIN INLINE: ai_packet_mapper.dart
// ============================================================================

List<PlayerTrack> mapServerTracksToPlayerTracks(List<AiTrackPacket> tracks) {
  return tracks.map((t) {
    // LIVE-слой должен двигаться по реальному bbox игрока.
    // Раньше здесь первым брался displayBBox/imagePoint. На некоторых версиях
    // AI-сервера displayBBox и imagePoint уже сглажены или относятся к карте
    // поля, а не к пикселям видео. Из-за этого рамки ехали медленно и неточно.
    // Для оверлея поверх видео надёжнее использовать сырой bbox, а displayBBox
    // оставить только fallback'ом.
    final bbox = t.bbox ?? t.displayBBox;

    Rect? rect;
    if (bbox != null) {
      rect = Rect.fromLTRB(
        bbox.left.toDouble(),
        bbox.top.toDouble(),
        bbox.right.toDouble(),
        bbox.bottom.toDouble(),
      );
    }

    // Для видео-оверлея точка игрока = нижний центр bbox.
    // imagePoint используем только если bbox отсутствует: иначе можно получить
    // координаты поля 0..1/метры и скорость будет почти 0.0 км/ч.
    final point = rect != null
        ? Offset(rect.center.dx, rect.bottom)
        : t.imagePoint != null
            ? Offset(t.imagePoint!.x.toDouble(), t.imagePoint!.y.toDouble())
            : Offset.zero;

    return PlayerTrack(
      id: t.trackId,
      boundPlayerId: t.playerId,
      boundPlayerName: t.playerName,
      color: t.teamTag == 'home'
          ? const Color(0xFF2563EB)
          : t.teamTag == 'away'
              ? const Color(0xFFDC2626)
              : Colors.redAccent,
      points: [
        TrackPoint(
          position: point,
          timeMs: 0,
          speed: t.speedKmh,
          vx: 0,
          vy: 0,
          ax: 0,
          ay: 0,
          rect: rect,
        ),
      ],
      createdAtMs: 0,
      lastSeenTimeMs: 0,
      speed: t.speedKmh,
      lockedBox: rect,
      teamTag: t.teamTag,
      jerseyNumber: t.jerseyNumber,
    );
  }).toList();
}



