class _TrackFilterState {
  final Offset position;
  final Offset velocity;
  final int timeMs;
  final double confidence;

  const _TrackFilterState({
    required this.position,
    required this.velocity,
    required this.timeMs,
    required this.confidence,
  });

  _TrackFilterState copyWith({
    Offset? position,
    Offset? velocity,
    int? timeMs,
    double? confidence,
  }) {
    return _TrackFilterState(
      position: position ?? this.position,
      velocity: velocity ?? this.velocity,
      timeMs: timeMs ?? this.timeMs,
      confidence: confidence ?? this.confidence,
    );
  }
}


List<dynamic> _aiJsonList(dynamic value) {
  if (value is List) return value;
  if (value is Map) {
    for (final key in const ['items', 'data', 'list', 'rows', 'events', 'tracks', 'players']) {
      final nested = value[key];
      if (nested is List) return nested;
    }
  }
  return const [];
}

int _aiJsonCount(dynamic value) {
  if (value is List) return value.length;
  if (value is num) return value.toInt();
  if (value is Map) return _aiJsonList(value).length;
  return 0;
}

