  void startLoop({
    required Future<List<DetectedPlayerBox>> Function(int) frameDetector,
    required int Function() currentTimeMs,
  }) {
    stopLoop();

    isRunning = true;
    notifyListeners();

    _loopTimer = Timer.periodic(Duration(milliseconds: sampleMs), (timer) async {
      if (_isProcessingFrame) return;

      _isProcessingFrame = true;
      try {
        final timeMs = currentTimeMs();
        final detections = await frameDetector(timeMs);

        _lastDetections = detections;
        _lastDetectionTimeMs = timeMs;

        if (isLocked) {
          updateLockedTrack(detections, timeMs);
        }
      } catch (e) {
        debugPrint('❌ AI tracking loop error: $e');
      } finally {
        _isProcessingFrame = false;
      }
    });
  }

  void stopLoop() {
    _loopTimer?.cancel();
    _loopTimer = null;
    _isProcessingFrame = false;
    isRunning = false;
    notifyListeners();
  }


List<Map<String, dynamic>> _buildTrackingFallbackTtd(Map<String, dynamic> json) {
  final frames = _aiJsonList(json['tracking_frames'])
      .whereType<Map>()
      .map((e) => Map<String, dynamic>.from(e))
      .toList();

  if (frames.isEmpty) return const [];

  int totalPlayers = 0;
  int homePlayers = 0;
  int awayPlayers = 0;
  int framesWithPlayers = 0;

  for (final frame in frames) {
    final players = (_aiJsonList(frame['players']).isNotEmpty
            ? _aiJsonList(frame['players'])
            : _aiJsonList(frame['tracks']))
        .whereType<Map>()
        .toList();

    if (players.isEmpty) continue;
    framesWithPlayers += 1;
    totalPlayers += players.length;

    for (final p in players) {
      final team = (p['team'] ?? p['team_key'] ?? '').toString();
      if (team == 'home') homePlayers += 1;
      if (team == 'away') awayPlayers += 1;
    }
  }

  if (framesWithPlayers == 0) return const [];

  final avgPlayers = (totalPlayers / framesWithPlayers).round();
  final firstTime = (frames.first['time_ms'] as num?)?.toInt() ?? 0;

  return [
    {
      'id': 'ai_tracking_players',
      'type': 'ai_tracking_players',
      'code': 'ai_tracking_players',
      'title': 'AI трекинг игроков',
      'event_title': 'AI трекинг игроков',
      'time_ms': firstTime,
      'start_ms': firstTime,
      'confidence': 0.72,
      'success': true,
      'is_positive': true,
      'description':
          'Мяч пока не найден, поэтому точные голы/передачи недоступны. Но AI уже видит игроков и строит карту активности.',
      'meta': {
        'source': 'ai_tracking_fallback',
        'avg_players': avgPlayers,
        'frames_with_players': framesWithPlayers,
        'home_detections': homePlayers,
        'away_detections': awayPlayers,
      },
    },
    {
      'id': 'ai_tracking_heatmap',
      'type': 'ai_tracking_heatmap',
      'code': 'ai_tracking_heatmap',
      'title': 'Тепловая карта готова',
      'event_title': 'Тепловая карта готова',
      'time_ms': firstTime,
      'start_ms': firstTime,
      'confidence': 0.68,
      'success': true,
      'is_positive': true,
      'description':
          'Доступны позиции, зоны активности и точки игроков на стандартном поле.',
      'meta': {
        'source': 'ai_tracking_fallback',
        'frames': frames.length,
      },
    },
  ];
}

void applyServerAnalysis(Map<String, dynamic> json) {
  debugPrint('✅ applyServerAnalysis CALLED');
  debugPrint('incoming keys = ${json.keys.toList()}');

  final eventsRaw = _aiJsonList(json['events']);
  final backendAutoTtdRaw = _aiJsonList(json['auto_ttd']);
  final fallbackAutoTtdRaw = backendAutoTtdRaw.isNotEmpty
      ? backendAutoTtdRaw
      : _buildTrackingFallbackTtd(json);
  final autoTtdRaw = fallbackAutoTtdRaw;

  final parsedEvents = eventsRaw
      .whereType<Map>()
      .map(
        (e) => AiDetectedEvent.fromBackendJson(
          Map<String, dynamic>.from(e),
        ),
      )
      .toList();

  final parsedSuggestions = autoTtdRaw
      .whereType<Map>()
      .map(
        (e) => AiTtdSuggestion.fromBackendJson(
          Map<String, dynamic>.from(e),
        ),
      )
      .toList();
      
      aiPassNetwork
  ..clear()
  ..addAll(
    _aiJsonList(json['pass_network'])
        .whereType<Map>()
        .map((e) => AiPassNetworkEdge.fromJson(Map<String, dynamic>.from(e))),
  );

aiAveragePositions
  ..clear()
  ..addAll(
    _aiJsonList(json['average_positions'])
        .whereType<Map>()
        .map((e) => AiAveragePosition.fromJson(Map<String, dynamic>.from(e))),
  );

aiDangerMoments
  ..clear()
  ..addAll(
    _aiJsonList(json['danger_moments'])
        .whereType<Map>()
        .map((e) => AiDangerMoment.fromJson(Map<String, dynamic>.from(e))),
  );

aiPlayerStats
  ..clear()
  ..addAll(
    _aiJsonList(json['player_stats'])
        .whereType<Map>()
        .map((e) => AiPlayerStat.fromJson(Map<String, dynamic>.from(e))),
  );

  autoEvents
    ..clear()
    ..addAll(parsedEvents);

  ttdSuggestions
    ..clear()
    ..addAll(parsedSuggestions);

  final summaryMap = json['summary'] is Map
      ? Map<String, dynamic>.from(json['summary'] as Map)
      : null;

  aiSummary = summaryMap;

  final directMatchStats = json['match_stats'] is Map
      ? Map<String, dynamic>.from(json['match_stats'] as Map)
      : null;

  final summaryMatchStats = summaryMap?['match_stats'] is Map
      ? Map<String, dynamic>.from(summaryMap!['match_stats'] as Map)
      : null;

  final rawMatchStats = directMatchStats ?? summaryMatchStats;

  if (rawMatchStats != null && rawMatchStats['match_stats'] is Map) {
    aiMatchStats = Map<String, dynamic>.from(
      rawMatchStats['match_stats'] as Map,
    );
  } else {
    aiMatchStats = rawMatchStats;
  }

  final directVideoMeta = json['video_meta'] is Map
      ? Map<String, dynamic>.from(json['video_meta'] as Map)
      : null;

  final summaryVideoMeta = summaryMap?['video'] is Map
      ? Map<String, dynamic>.from(summaryMap!['video'] as Map)
      : null;

  aiVideoMeta = directVideoMeta ?? summaryVideoMeta;

  aiPossessionTimeline = _aiJsonList(json['possession_timeline'])
      .whereType<Map>()
      .map((e) => Map<String, dynamic>.from(e))
      .toList();

  debugPrint('✅ Server AI applied');
  debugPrint('   events: ${autoEvents.length}');
  debugPrint('   ttd suggestions: ${ttdSuggestions.length}');
  debugPrint('   aiSummary = $aiSummary');
  debugPrint('   aiMatchStats = $aiMatchStats');
  debugPrint('   aiVideoMeta = $aiVideoMeta');
  debugPrint('   aiPossessionTimeline: ${aiPossessionTimeline.length}');

  notifyListeners();
}
