  void setDetectionsForSelection(List<DetectedPlayerBox> detections, int timeMs) {
    _lastDetections = detections;
    _lastDetectionTimeMs = timeMs;
  }

  void selectTrackByTap(Offset tapPosition) {
    if (_lastDetections.isEmpty) {
      debugPrint('⚠️ No detections available for tap-lock');
      return;
    }

    lockOnDetections(
      tapPosition: tapPosition,
      detections: _lastDetections,
      timeMs: _lastDetectionTimeMs,
    );
  }

  void lockOnDetections({
    required Offset tapPosition,
    required List<DetectedPlayerBox> detections,
    required int timeMs,
  }) {
    if (detections.isEmpty) return;

    DetectedPlayerBox? best;
    double bestDistance = double.infinity;

    for (final d in detections) {
      final dist = (_footPoint(d.rect) - tapPosition).distance;
      if (dist < bestDistance) {
        bestDistance = dist;
        best = d;
      }
    }

    if (best == null) return;

    final initialPosition = _footPoint(best.rect);

    _filterState = _TrackFilterState(
      position: initialPosition,
      velocity: Offset.zero,
      timeMs: timeMs,
      confidence: 1.0,
    );

    final newTrack = PlayerTrack(
      id: 'track_$timeMs',
      color: Colors.red,
      points: [
        TrackPoint(
          position: initialPosition,
          timeMs: timeMs,
          speed: 0,
          rect: best.rect,
          vx: 0,
          vy: 0,
          ax: 0,
          ay: 0,
        ),
      ],
      speed: 0,
      boundPlayerId: selectedTrack?.boundPlayerId,
      boundPlayerName: selectedTrack?.boundPlayerName ?? 'Игрок',
      createdAtMs: timeMs,
      lastSeenTimeMs: timeMs,
      lockedBox: best.rect,
      teamTag: selectedTrack?.teamTag,
      jerseyNumber: selectedTrack?.jerseyNumber,
    );

    lockedTrack = newTrack;
    lockedRect = best.rect;
    lockedPosition = initialPosition;

    isLocked = true;
    isSelectingTarget = false;
    _missedLockedFrames = 0;
    _lastUpdateTimeMs = timeMs;
    _lastVelocity = Offset.zero;
    _lastSpeedKmh = 0;

    tracks = [newTrack];
    selectedTrackId = newTrack.id;
    selectedTrack = newTrack;

    _recalculateLiveStats(newTrack);
    notifyListeners();
  }

  void updateLockedTrack(List<DetectedPlayerBox> detections, int timeMs) {
    if (!isLocked || lockedTrack == null || lockedRect == null || _filterState == null) {
      return;
    }

    final prevTrack = lockedTrack!;
    final prevRect = lockedRect!;
    final prevFilter = _filterState!;

    _lastUpdateTimeMs = timeMs;

    if (detections.isEmpty) {
      _missedLockedFrames++;

      if (_missedLockedFrames > _maxMissedLockedFrames) {
        clearLock();
      } else {
        final predictedOnly = _predictFilteredPosition(prevFilter, timeMs);

        _filterState = prevFilter.copyWith(
          position: predictedOnly,
          timeMs: timeMs,
          confidence: (prevFilter.confidence * 0.92).clamp(0.15, 1.0),
        );

        notifyListeners();
      }
      return;
    }

    final predictedPoint = _predictFilteredPosition(prevFilter, timeMs);

    DetectedPlayerBox? best;
    double bestScore = double.infinity;

    for (final d in detections) {
      final measuredPoint = _footPoint(d.rect);
      final pointDistance = (measuredPoint - predictedPoint).distance;
      final iou = _computeIoU(prevRect, d.rect);
      final sizePenalty = _sizePenalty(prevRect, d.rect);

      final score = pointDistance - (iou * 120) + (sizePenalty * 40);

      if (score < bestScore) {
        bestScore = score;
        best = d;
      }
    }

    if (best == null) {
      _missedLockedFrames++;
      if (_missedLockedFrames > _maxMissedLockedFrames) {
        clearLock();
      } else {
        notifyListeners();
      }
      return;
    }

    final measuredPointRaw = _footPoint(best.rect);
    final measuredPoint = _softClampMeasurement(
      predicted: predictedPoint,
      measured: measuredPointRaw,
      maxJumpPx: _maxMeasurementJumpPx,
    );

    final measurementConfidence = _estimateMeasurementConfidence(
      previousRect: prevRect,
      nextRect: best.rect,
      predictedPoint: predictedPoint,
      measuredPoint: measuredPointRaw,
    );

    if ((measuredPointRaw - predictedPoint).distance > _hardRejectJumpPx &&
        measurementConfidence < 0.20) {
      _missedLockedFrames++;

      if (_missedLockedFrames > _maxMissedLockedFrames) {
        clearLock();
      } else {
        _filterState = prevFilter.copyWith(
          position: predictedPoint,
          timeMs: timeMs,
          confidence: (prevFilter.confidence * 0.90).clamp(0.12, 1.0),
        );
        notifyListeners();
      }
      return;
    }

    _missedLockedFrames = 0;

    final updatedFilter = _updateAlphaBetaFilter(
      previous: prevFilter,
      measurement: measuredPoint,
      timeMs: timeMs,
      confidence: measurementConfidence,
    );

    _filterState = updatedFilter;

    final newRect = _smoothRectFast(prevRect, best.rect, _positionSmoothFactor);

    final filteredPosition = updatedFilter.position;
    final dt = ((timeMs - prevTrack.points.last.timeMs) / 1000.0).clamp(0.04, 0.25);

    final vx = updatedFilter.velocity.dx;
    final vy = updatedFilter.velocity.dy;

    final prevPoint = prevTrack.points.last;
    final ax = (vx - prevPoint.vx) / dt;
    final ay = (vy - prevPoint.vy) / dt;

    final previewPoints = List<TrackPoint>.from(prevTrack.points)
      ..add(
        TrackPoint(
          position: filteredPosition,
          timeMs: timeMs,
          speed: 0,
          rect: newRect,
          vx: vx,
          vy: vy,
          ax: ax,
          ay: ay,
        ),
      );

    final rawWindowSpeed = _computeWindowSpeedKmhFromPoints(previewPoints);
    final displaySpeed = _smoothDisplaySpeed(prevPoint.speed, rawWindowSpeed);

    final updatedPoints = List<TrackPoint>.from(prevTrack.points)
      ..add(
        TrackPoint(
          position: filteredPosition,
          timeMs: timeMs,
          speed: displaySpeed,
          rect: newRect,
          vx: vx,
          vy: vy,
          ax: ax,
          ay: ay,
        ),
      );

    final trimmedPoints = updatedPoints.length > _maxPointsPerTrack
        ? updatedPoints.sublist(updatedPoints.length - _maxPointsPerTrack)
        : updatedPoints;

    final updatedTrack = PlayerTrack(
      id: prevTrack.id,
      color: prevTrack.color,
      points: trimmedPoints,
      speed: displaySpeed,
      boundPlayerId: prevTrack.boundPlayerId,
      boundPlayerName: prevTrack.boundPlayerName,
      createdAtMs: prevTrack.createdAtMs,
      lastSeenTimeMs: timeMs,
      lockedBox: newRect,
      teamTag: prevTrack.teamTag,
      jerseyNumber: prevTrack.jerseyNumber,
    );

    lockedTrack = updatedTrack;
    lockedRect = newRect;
    lockedPosition = filteredPosition;

    _lastVelocity = Offset(vx, vy);
    _lastSpeedKmh = displaySpeed;

    tracks = [updatedTrack];
    selectedTrackId = updatedTrack.id;
    selectedTrack = updatedTrack;

    _recalculateLiveStats(updatedTrack);

    if (!useServerAiResults) {
      _generateAiEvents(updatedTrack);
      _generateTtdSuggestions(updatedTrack);
    }

    notifyListeners();
  }

  Offset _footPoint(Rect rect) => Offset(rect.center.dx, rect.bottom);

  Offset _predictFilteredPosition(_TrackFilterState state, int timeMs) {
    final dt = ((timeMs - state.timeMs) / 1000.0).clamp(0.0, 0.25);
    return Offset(
      state.position.dx + state.velocity.dx * dt,
      state.position.dy + state.velocity.dy * dt,
    );
  }

  _TrackFilterState _updateAlphaBetaFilter({
    required _TrackFilterState previous,
    required Offset measurement,
    required int timeMs,
    required double confidence,
  }) {
    final dt = ((timeMs - previous.timeMs) / 1000.0).clamp(0.016, 0.25);

    final predictedPosition = Offset(
      previous.position.dx + previous.velocity.dx * dt,
      previous.position.dy + previous.velocity.dy * dt,
    );

    final predictedVelocity = previous.velocity;

    final residual = measurement - predictedPosition;

    final alpha = _alphaBetaAlpha * confidence;
    final beta = _alphaBetaBeta * confidence;

    final correctedPosition = Offset(
      predictedPosition.dx + residual.dx * alpha,
      predictedPosition.dy + residual.dy * alpha,
    );

    final correctedVelocity = Offset(
      predictedVelocity.dx + (residual.dx * beta / dt),
      predictedVelocity.dy + (residual.dy * beta / dt),
    );

    return _TrackFilterState(
      position: correctedPosition,
      velocity: correctedVelocity,
      timeMs: timeMs,
      confidence: confidence,
    );
  }

  double _estimateMeasurementConfidence({
    required Rect previousRect,
    required Rect nextRect,
    required Offset predictedPoint,
    required Offset measuredPoint,
  }) {
    final jump = (measuredPoint - predictedPoint).distance;
    final iou = _computeIoU(previousRect, nextRect);
    final sizePenalty = _sizePenalty(previousRect, nextRect);

    double confidence = 1.0;

    if (jump > _maxMeasurementJumpPx) {
      confidence *= 0.45;
    }

    if (jump > _hardRejectJumpPx) {
      confidence *= 0.15;
    }

    confidence *= (0.55 + iou * 0.45);
    confidence *= (1.0 - sizePenalty.clamp(0.0, 0.6) * 0.7);

    return confidence.clamp(0.12, 1.0);
  }

  Offset _softClampMeasurement({
    required Offset predicted,
    required Offset measured,
    required double maxJumpPx,
  }) {
    final delta = measured - predicted;
    final dist = delta.distance;

    if (dist <= maxJumpPx || dist == 0) return measured;

    final k = maxJumpPx / dist;
    return Offset(
      predicted.dx + delta.dx * k,
      predicted.dy + delta.dy * k,
    );
  }

  double _computeWindowSpeedKmhFromPoints(List<TrackPoint> points) {
    if (points.length < 2) return 0;

    final recent = points.length > 8
        ? points.sublist(points.length - 8)
        : points;

    double totalDistanceMeters = 0;
    double totalSeconds = 0;

    for (int i = 1; i < recent.length; i++) {
      final p1 = recent[i - 1];
      final p2 = recent[i];

      final dt = ((p2.timeMs - p1.timeMs) / 1000.0).clamp(0.04, 0.20);
      final dx = p2.position.dx - p1.position.dx;
      final dy = p2.position.dy - p1.position.dy;
      final distPx = sqrt(dx * dx + dy * dy);

      final localScale = _localPixelsToMeters(p2.position.dy);

      totalDistanceMeters += distPx * localScale;
      totalSeconds += dt;
    }

    if (totalSeconds <= 0) return 0;

    final kmh = (totalDistanceMeters / totalSeconds) * 3.6;
    return kmh.clamp(0, _maxPlayerSpeedKmh);
  }

  double _localPixelsToMeters(double y) {
    final normalizedY = (y / 1080.0).clamp(0.0, 1.0);

    final farScale = _pixelsToMeters * 1.85;
    final nearScale = _pixelsToMeters * 0.72;

    return (farScale + (nearScale - farScale) * normalizedY).toDouble();
  }

  double _smoothDisplaySpeed(double previous, double next) {
    double factor = _displaySmoothFactor;

    if ((next - previous).abs() > 10) {
      factor = 0.08;
    }

    final value = previous + (next - previous) * factor;
    return value.clamp(0, _maxPlayerSpeedKmh);
  }

  Offset _predictNextPosition(PlayerTrack track, int timeMs, int deltaTimeMs) {
    if (_filterState != null) {
      return _predictFilteredPosition(_filterState!, timeMs);
    }

    if (track.points.isEmpty) return Offset.zero;
    return track.points.last.position;
  }

  Offset getPredictedPositionForTrack(PlayerTrack track, int currentVideoTimeMs) {
    if (_filterState != null) {
      return _predictFilteredPosition(_filterState!, currentVideoTimeMs);
    }

    if (track.points.isEmpty) return Offset.zero;
    return track.points.last.position;
  }

  Rect? getPredictedRectForTrack(PlayerTrack track, int currentVideoTimeMs) {
    if (track.points.isEmpty) return null;

    final last = track.points.last;
    final baseRect = last.rect;
    if (baseRect == null) return null;

    final predictedPos = getPredictedPositionForTrack(track, currentVideoTimeMs);
    final offset = predictedPos - last.position;

    return baseRect.shift(offset);
  }

  Rect _smoothRectFast(Rect prev, Rect next, double t) {
    return Rect.fromLTRB(
      prev.left * (1 - t) + next.left * t,
      prev.top * (1 - t) + next.top * t,
      prev.right * (1 - t) + next.right * t,
      prev.bottom * (1 - t) + next.bottom * t,
    );
  }

  Rect _smoothRect(Rect prev, Rect next, double t) {
    return _smoothRectFast(prev, next, t);
  }

  double _sizePenalty(Rect a, Rect b) {
    final areaA = a.width * a.height;
    final areaB = b.width * b.height;
    if (areaA <= 0) return 0;
    return ((areaB - areaA).abs() / areaA);
  }

  double _computeIoU(Rect a, Rect b) {
    final left = max(a.left, b.left);
    final top = max(a.top, b.top);
    final right = min(a.right, b.right);
    final bottom = min(a.bottom, b.bottom);

    if (right <= left || bottom <= top) return 0.0;

    final intersection = (right - left) * (bottom - top);
    final union = a.width * a.height + b.width * b.height - intersection;
    if (union <= 0) return 0.0;

    return intersection / union;
  }

  bool isSprintNow() {
    if (lockedTrack == null || lockedTrack!.points.isEmpty) return false;
    return lockedTrack!.points.last.speed >= 24.0;
  }

  double currentAcceleration() {
    if (lockedTrack == null || lockedTrack!.points.isEmpty) return 0;
    final p = lockedTrack!.points.last;
    return sqrt(p.ax * p.ax + p.ay * p.ay);
  }

  double? getCurrentSelectedPlayerSpeed() {
    if (lockedTrack != null && lockedTrack!.points.isNotEmpty) {
      return lockedTrack!.points.last.speed;
    }
    return null;
  }

  void bindSelectedTrackToPlayer({
    required int playerId,
    required String playerName,
  }) {
    if (lockedTrack == null) return;

    lockedTrack!.boundPlayerId = playerId;
    lockedTrack!.boundPlayerName = playerName;

    if (tracks.isNotEmpty) {
      tracks[0].boundPlayerId = playerId;
      tracks[0].boundPlayerName = playerName;
    }

    if (selectedTrack != null) {
      selectedTrack!.boundPlayerId = playerId;
      selectedTrack!.boundPlayerName = playerName;
    }

    debugPrint('✅ Locked track bound to player $playerName');
    notifyListeners();
  }

  void updateBall({
    required Rect rect,
    required int timeMs,
    double confidence = 1.0,
  }) {
    final point = BallPoint(
      position: rect.center,
      timeMs: timeMs,
      rect: rect,
      confidence: confidence,
    );

    final updatedPoints = List<BallPoint>.from(ballTrack?.points ?? [])..add(point);

    final trimmedPoints = updatedPoints.length > 50
        ? updatedPoints.sublist(updatedPoints.length - 50)
        : updatedPoints;

    ballTrack = BallTrack(
      points: trimmedPoints,
      lastSeenTimeMs: timeMs,
      lastRect: rect,
    );

    updateBallPossession(timeMs, rect.center);
    detectPassFromBall(timeMs);

    notifyListeners();
  }

  String? findNearestTrackToBall(
    Offset ballPos, {
    double maxDistance = 46,
  }) {
    String? bestId;
    double bestDistance = double.infinity;

    for (final track in tracks) {
      final pos = track.currentPosition;
      if (pos == null) continue;

      final d = (pos - ballPos).distance;
      if (d < bestDistance && d <= maxDistance) {
        bestDistance = d;
        bestId = track.id;
      }
    }

    return bestId;
  }

  void updateBallPossession(int timeMs, Offset ballPos) {
    final nextOwnerId = findNearestTrackToBall(ballPos);

    if (nextOwnerId == null) return;

    final nextOwnerIndex = tracks.indexWhere((t) => t.id == nextOwnerId);
    if (nextOwnerIndex == -1) return;

    final nextOwner = tracks[nextOwnerIndex];

    if (currentBallOwnerTrackId == null) {
      currentBallOwnerTrackId = nextOwner.id;
      currentBallOwnerStartedAtMs = timeMs;
      currentBallOwnerName = nextOwner.boundPlayerName;
      currentBallOwnerTeamTag = nextOwner.teamTag;
      return;
    }

    if (currentBallOwnerTrackId != nextOwner.id) {
      possessionSegments.insert(
        0,
        BallPossessionSegment(
          trackId: currentBallOwnerTrackId!,
          playerName: currentBallOwnerName ?? 'Игрок',
          teamTag: currentBallOwnerTeamTag,
          startedAtMs: currentBallOwnerStartedAtMs ?? timeMs,
          endedAtMs: timeMs,
        ),
      );

      if (possessionSegments.length > 100) {
        possessionSegments.removeRange(100, possessionSegments.length);
      }

      currentBallOwnerTrackId = nextOwner.id;
      currentBallOwnerStartedAtMs = timeMs;
      currentBallOwnerName = nextOwner.boundPlayerName;
      currentBallOwnerTeamTag = nextOwner.teamTag;
    }
  }

  void registerPassEdge(String fromTrackId, String toTrackId) {
    final index = passEdges.indexWhere(
      (e) => e.fromTrackId == fromTrackId && e.toTrackId == toTrackId,
    );

    if (index == -1) {
      final fromTrackIndex = tracks.indexWhere((t) => t.id == fromTrackId);
      final toTrackIndex = tracks.indexWhere((t) => t.id == toTrackId);

      final fromTrack = fromTrackIndex != -1 ? tracks[fromTrackIndex] : null;
      final toTrack = toTrackIndex != -1 ? tracks[toTrackIndex] : null;

      passEdges.add(
        PassEdge(
          fromTrackId: fromTrackId,
          toTrackId: toTrackId,
          count: 1,
          fromTeamTag: fromTrack?.teamTag,
          toTeamTag: toTrack?.teamTag,
        ),
      );
    } else {
      final current = passEdges[index];
      passEdges[index] = current.copyWith(count: current.count + 1);
    }
  }

  void detectPassFromBall(int timeMs) {
    final ball = ballTrack?.lastPoint;
    if (ball == null) return;

    final currentOwner = findNearestTrackToBall(ball.position);
    if (currentOwner == null) return;

    if (_lastBallOwnerTrackId == null) {
      _lastBallOwnerTrackId = currentOwner;
      _lastBallOwnerTimeMs = timeMs;
      return;
    }

    if (currentOwner != _lastBallOwnerTrackId &&
        timeMs - _lastBallOwnerTimeMs < 2200) {
      final fromTrackIndex = tracks.indexWhere((t) => t.id == _lastBallOwnerTrackId);
      final toTrackIndex = tracks.indexWhere((t) => t.id == currentOwner);

      if (fromTrackIndex != -1 && toTrackIndex != -1) {
        final fromTrack = tracks[fromTrackIndex];
        final toTrack = tracks[toTrackIndex];

        final fromPos = fromTrack.currentPosition ?? fromTrack.points.last.position;
        final toPos = toTrack.currentPosition ?? toTrack.points.last.position;

        passArrows.insert(
          0,
          PassArrow(
            fromTrackId: fromTrack.id,
            toTrackId: toTrack.id,
            from: fromPos,
            to: toPos,
            timeMs: timeMs,
            confidence: 0.72,
          ),
        );

        if (passArrows.length > 20) {
          passArrows.removeRange(20, passArrows.length);
        }

        registerPassEdge(fromTrack.id, toTrack.id);
      }
    }

    _lastBallOwnerTrackId = currentOwner;
    _lastBallOwnerTimeMs = timeMs;
  }

  void assignTrackTeam(String trackId, String teamTag) {
    final index = tracks.indexWhere((t) => t.id == trackId);
    if (index == -1) return;

    final track = tracks[index];

    Color nextColor = track.color;
    if (teamTag == 'home') {
      nextColor = const Color(0xFF2563EB);
    } else if (teamTag == 'away') {
      nextColor = const Color(0xFFDC2626);
    }

    tracks[index] = track.copyWith(
      color: nextColor,
      teamTag: teamTag,
    );

    if (lockedTrack != null && lockedTrack!.id == trackId) {
      lockedTrack = tracks[index];
    }
    if (selectedTrack != null && selectedTrack!.id == trackId) {
      selectedTrack = tracks[index];
    }

    notifyListeners();
  }

  Map<String, dynamic> exportJson() {
    return {
      'locked': isLocked,
      'track': lockedTrack?.toJson(),
      'timestamp': DateTime.now().toIso8601String(),
      'stats': _calculateStats(),
      'is_sprint_now': isSprintNow(),
      'current_acceleration': currentAcceleration(),
      'auto_events': autoEvents
          .map((e) => {
                'type': e.type,
                'title': e.title,
                'subtitle': e.subtitle,
                'timeMs': e.timeMs,
                'confidence': e.confidence,
                'meta': e.meta,
              })
          .toList(),
      'ttd_suggestions': ttdSuggestions
          .map((e) => {
                'code': e.code,
                'title': e.title,
                'section': e.section,
                'timeMs': e.timeMs,
                'confidence': e.confidence,
                'success': e.success,
                'meta': e.meta,
              })
          .toList(),
      'ball_track': ballTrack == null
          ? null
          : {
              'lastSeenTimeMs': ballTrack!.lastSeenTimeMs,
              'points': ballTrack!.points.map((e) => e.toJson()).toList(),
            },
      'current_ball_owner': {
        'trackId': currentBallOwnerTrackId,
        'playerName': currentBallOwnerName,
        'teamTag': currentBallOwnerTeamTag,
        'startedAtMs': currentBallOwnerStartedAtMs,
      },
      'possession_segments': possessionSegments
          .map((e) => {
                'trackId': e.trackId,
                'playerName': e.playerName,
                'teamTag': e.teamTag,
                'startedAtMs': e.startedAtMs,
                'endedAtMs': e.endedAtMs,
                'durationMs': e.durationMs,
              })
          .toList(),
      'pass_arrows': passArrows
          .map((e) => {
                'fromTrackId': e.fromTrackId,
                'toTrackId': e.toTrackId,
                'from': {'x': e.from.dx, 'y': e.from.dy},
                'to': {'x': e.to.dx, 'y': e.to.dy},
                'timeMs': e.timeMs,
                'confidence': e.confidence,
              })
          .toList(),
      'pass_edges': passEdges
          .map((e) => {
                'fromTrackId': e.fromTrackId,
                'toTrackId': e.toTrackId,
                'count': e.count,
                'fromTeamTag': e.fromTeamTag,
                'toTeamTag': e.toTeamTag,
              })
          .toList(),
      'ai_summary': aiSummary,
      'ai_match_stats': aiMatchStats,
      'ai_video_meta': aiVideoMeta,
      'ai_possession_timeline': aiPossessionTimeline,
      'pass_network': aiPassNetwork.map((e) => {
  'from_track_id': e.fromTrackId,
  'to_track_id': e.toTrackId,
  'team': e.team,
  'count': e.count,
  'successful': e.successful,
  'avg_start_x': e.avgStartX,
  'avg_start_y': e.avgStartY,
  'avg_end_x': e.avgEndX,
  'avg_end_y': e.avgEndY,
}).toList(),

'average_positions': aiAveragePositions.map((e) => {
  'track_id': e.trackId,
  'team': e.team,
  'player_name': e.playerName,
  'avg_x': e.avgX,
  'avg_y': e.avgY,
  'samples': e.samples,
}).toList(),

'danger_moments': aiDangerMoments.map((e) => {
  'time_ms': e.timeMs,
  'team': e.team,
  'type': e.type,
  'title': e.title,
  'danger_score': e.dangerScore,
}).toList(),

'player_stats': aiPlayerStats.map((e) => {
  'track_id': e.trackId,
  'team': e.team,
  'player_name': e.playerName,
  'touches': e.touches,
  'passes': e.passes,
  'successful_passes': e.successfulPasses,
  'shots': e.shots,
  'interceptions': e.interceptions,
  'distance_m': e.distanceM,
  'max_speed_kmh': e.maxSpeedKmh,
  'rating': e.rating,
}).toList(),

    };
  }

  Map<String, dynamic> _calculateStats() {
    if (lockedTrack == null) {
      return {
        'total_tracks': 0,
        'total_points': 0,
        'total_distance_m': 0.0,
        'max_speed_kmh': 0.0,
      };
    }

    double totalDistance = 0;
    double maxSpeed = 0;
    final pts = lockedTrack!.points;

    for (final point in pts) {
      maxSpeed = max(maxSpeed, point.speed);
    }

    for (int i = 1; i < pts.length; i++) {
      final p1 = pts[i - 1].position;
      final p2 = pts[i].position;
      final dx = p2.dx - p1.dx;
      final dy = p2.dy - p1.dy;
      totalDistance += sqrt(dx * dx + dy * dy) * _localPixelsToMeters(p2.dy);
    }

    return {
      'total_tracks': 1,
      'total_points': pts.length,
      'total_distance_m': totalDistance,
      'max_speed_kmh': maxSpeed,
    };
  }

  void calibratePixelsToMeters(double knownDistanceMeters, double pixelsDistance) {
    if (pixelsDistance > 0) {
      _pixelsToMeters = knownDistanceMeters / pixelsDistance;
      debugPrint('📏 Calibrated pixelsToMeters = $_pixelsToMeters');
      notifyListeners();
    }
  }

  void autoCalibrateStandardField(double fieldPixelsLength) {
    if (fieldPixelsLength > 0) {
      _pixelsToMeters = 105.0 / fieldPixelsLength;

      debugPrint('📏 Auto calibration (field):');
      debugPrint(
        '   fieldPixelsLength = ${fieldPixelsLength.toStringAsFixed(1)} px',
      );
      debugPrint(
        '   scale = 1px = ${(_pixelsToMeters * 100).toStringAsFixed(1)} cm',
      );

      notifyListeners();
    }
  }

  bool get isCalibrating => false;
  double get currentScale => _pixelsToMeters;
  String get currentScaleText =>
      '1px = ${(_pixelsToMeters * 100).toStringAsFixed(1)}cm';

  void setTrackingSensitivity({
    required double positionSmoothFactor,
    required double speedSmoothFactor,
    required double maxJumpDistance,
    required bool usePrediction,
    required double predictionFactor,
  }) {
    _positionSmoothFactor = positionSmoothFactor.clamp(0.08, 0.70);
    _speedSmoothFactor = speedSmoothFactor.clamp(0.05, 0.50);
    _maxJumpDistance = maxJumpDistance.clamp(60, 250);
    _usePrediction = usePrediction;
    _predictionFactor = predictionFactor.clamp(0.0, 0.5);

    debugPrint('⚙️ Tracking sensitivity updated:');
    debugPrint('   positionSmooth=$_positionSmoothFactor');
    debugPrint('   speedSmooth=$_speedSmoothFactor');
    debugPrint('   maxJump=$_maxJumpDistance');
    debugPrint('   usePrediction=$_usePrediction');
    debugPrint('   predictionFactor=$_predictionFactor');
  }

  void setAdvancedTrackingTuning({
    double? alpha,
    double? beta,
    double? maxMeasurementJumpPx,
    double? hardRejectJumpPx,
    double? displaySmoothFactor,
    double? pixelsToMeters,
    int? sampleIntervalMs,
  }) {
    if (alpha != null) {
      _alphaBetaAlpha = alpha.clamp(0.08, 0.45);
    }
    if (beta != null) {
      _alphaBetaBeta = beta.clamp(0.01, 0.16);
    }
    if (maxMeasurementJumpPx != null) {
      _maxMeasurementJumpPx = maxMeasurementJumpPx.clamp(30.0, 180.0);
    }
    if (hardRejectJumpPx != null) {
      _hardRejectJumpPx = hardRejectJumpPx.clamp(60.0, 260.0);
    }
    if (displaySmoothFactor != null) {
      _displaySmoothFactor = displaySmoothFactor.clamp(0.05, 0.45);
    }
    if (pixelsToMeters != null) {
      _pixelsToMeters = pixelsToMeters.clamp(0.005, 0.20);
    }
    if (sampleIntervalMs != null) {
      sampleMs = sampleIntervalMs.clamp(33, 250);
    }

    notifyListeners();
  }

  void _recalculateLiveStats(PlayerTrack track) {
    if (track.points.isEmpty) {
      averageSpeedKmh = 0;
      maxSpeedKmh = 0;
      totalDistanceMeters = 0;
      sprintCount = 0;
      return;
    }

    double sumSpeed = 0;
    double maxSpeed = 0;
    double totalDistance = 0;

    int sprints = 0;
    bool sprintOpen = false;

    for (int i = 0; i < track.points.length; i++) {
      final p = track.points[i];
      sumSpeed += p.speed;
      if (p.speed > maxSpeed) maxSpeed = p.speed;

      if (p.speed >= 24.0 && !sprintOpen) {
        sprintOpen = true;
        sprints++;
      } else if (p.speed < 20.0) {
        sprintOpen = false;
      }

      if (i > 0) {
        final prev = track.points[i - 1].position;
        final dx = p.position.dx - prev.dx;
        final dy = p.position.dy - prev.dy;
        totalDistance += sqrt(dx * dx + dy * dy) * _localPixelsToMeters(p.position.dy);
      }
    }

    averageSpeedKmh = sumSpeed / track.points.length;
    maxSpeedKmh = maxSpeed;
    totalDistanceMeters = totalDistance;
    sprintCount = sprints;
  }

  void _generateAiEvents(PlayerTrack track) {
    if (track.points.length < 3) return;

    final last = track.points.last;
    final prev = track.points[track.points.length - 2];

    final accel = sqrt(last.ax * last.ax + last.ay * last.ay);
    final speed = last.speed;

    final directionNow = atan2(last.vy, last.vx);
    final directionPrev = atan2(prev.vy, prev.vx);
    double directionDelta = (directionNow - directionPrev).abs();
    if (directionDelta > pi) {
      directionDelta = 2 * pi - directionDelta;
    }

    if (speed >= 24.0 && last.timeMs - _lastSprintEventTimeMs > 4000) {
      _lastSprintEventTimeMs = last.timeMs;

      autoEvents.insert(
        0,
        AiDetectedEvent(
          type: 'sprint',
          title: 'Рывок',
          subtitle: 'Игрок резко набрал высокую скорость',
          timeMs: last.timeMs,
          confidence: 0.86,
          icon: Icons.flash_on_rounded,
          color: const Color(0xFFF59E0B),
          meta: {'speed': speed},
        ),
      );
    }

    if (accel >= 120.0 && last.timeMs - _lastAccelerationEventTimeMs > 3500) {
      _lastAccelerationEventTimeMs = last.timeMs;
      accelerationBurstCount++;

      autoEvents.insert(
        0,
        AiDetectedEvent(
          type: 'acceleration',
          title: 'Резкое ускорение',
          subtitle: 'Выраженный импульс ускорения',
          timeMs: last.timeMs,
          confidence: 0.78,
          icon: Icons.trending_up_rounded,
          color: const Color(0xFF16A34A),
          meta: {'acceleration': accel},
        ),
      );
    }

    if (directionDelta >= 0.65 &&
        speed >= 8.0 &&
        last.timeMs - _lastDirectionEventTimeMs > 3000) {
      _lastDirectionEventTimeMs = last.timeMs;
      directionChangeCount++;

      autoEvents.insert(
        0,
        AiDetectedEvent(
          type: 'direction_change',
          title: 'Смена направления',
          subtitle: 'Возможный манёвр, обыгрыш или уход от соперника',
          timeMs: last.timeMs,
          confidence: 0.74,
          icon: Icons.turn_right_rounded,
          color: const Color(0xFF2563EB),
          meta: {'delta': directionDelta},
        ),
      );
    }

    if (autoEvents.length > 50) {
      autoEvents.removeRange(50, autoEvents.length);
    }
  }

  void _generateTtdSuggestions(PlayerTrack track) {
    if (track.points.length < 3) return;

    final last = track.points.last;
    final prev = track.points[track.points.length - 2];

    final accel = sqrt(last.ax * last.ax + last.ay * last.ay);

    final directionNow = atan2(last.vy, last.vx);
    final directionPrev = atan2(prev.vy, prev.vx);
    double directionDelta = (directionNow - directionPrev).abs();
    if (directionDelta > pi) {
      directionDelta = 2 * pi - directionDelta;
    }

    if (last.timeMs - _lastTtdSuggestionTimeMs < 2500) return;

    if (directionDelta >= 0.70 && last.speed >= 10.0) {
      _lastTtdSuggestionTimeMs = last.timeMs;

      ttdSuggestions.insert(
        0,
        AiTtdSuggestion(
          code: 'feint_dribble',
          title: 'Финт / дриблинг',
          section: 'Основные действия',
          timeMs: last.timeMs,
          confidence: 0.72,
          success: true,
          meta: {
            'speed': last.speed,
            'direction_delta': directionDelta,
          },
        ),
      );
    } else if (last.speed >= 6.0 && last.speed <= 18.0 && accel >= 90.0) {
      _lastTtdSuggestionTimeMs = last.timeMs;

      ttdSuggestions.insert(
        0,
        AiTtdSuggestion(
          code: 'forward_short',
          title: 'Передача вперед короткая',
          section: 'Передачи',
          timeMs: last.timeMs,
          confidence: 0.64,
          success: true,
          meta: {
            'speed': last.speed,
            'acceleration': accel,
          },
        ),
      );
    } else if (last.speed >= 12.0 && accel >= 130.0) {
      _lastTtdSuggestionTimeMs = last.timeMs;

      ttdSuggestions.insert(
        0,
        AiTtdSuggestion(
          code: 'interception',
          title: 'Перехват',
          section: 'Основные действия',
          timeMs: last.timeMs,
          confidence: 0.58,
          success: true,
          meta: {
            'speed': last.speed,
            'acceleration': accel,
          },
        ),
      );
    }

    if (ttdSuggestions.length > 50) {
      ttdSuggestions.removeRange(50, ttdSuggestions.length);
    }
  }
}

class TrackMotionResult {
  final double speedKmh;
  final double vx;
  final double vy;
  final double ax;
  final double ay;

  const TrackMotionResult({
    required this.speedKmh,
    required this.vx,
    required this.vy,
    required this.ax,
    required this.ay,
  });
}



// ============================================================================
// BEGIN INLINE: ai_video_analysis_controller.dart
// ============================================================================

class AiVideoAnalysisController extends ChangeNotifier {
  final AiVideoAnalysisService service;

  AiVideoAnalysisController({
    required this.service,
  });

  String? jobId;
  bool isCreatingJob = false;
  bool isPollingStatus = false;
  bool isLoadingFrame = false;
  bool isSendingCalibration = false;
  bool isLoadingSummary = false;
  bool isStartingRun = false;

  String? errorText;

  AiJobStatusResponse? jobStatus;
  AiFramePacket? currentFramePacket;
  AiPlayerSummary? currentPlayerSummary;

  int _lastRequestedTimeMs = -1;
  Timer? _frameDebounce;
  bool _disposed = false;

  void _safeNotify() {
    if (!_disposed) {
      notifyListeners();
    }
  }

  bool get hasJob => jobId != null && jobId!.isNotEmpty;
  bool get isReady => jobStatus?.isDone == true;

  Future<String?> createAnalysisJob({
    int? matchId,
    String? videoUrl,
    String? localVideoPath,
  }) async {
    isCreatingJob = true;
    errorText = null;
    _safeNotify();

    try {
      final response = await service.createJob(
        AiJobCreateRequest(
          matchId: matchId,
          videoUrl: videoUrl,
          localVideoPath: localVideoPath,
        ),
      );

      jobId = response.jobId;
      debugPrint('✅ Job created: $jobId');
      _safeNotify();
      return response.jobId;
    } catch (e) {
      errorText = e.toString();
      debugPrint('❌ Failed to create job: $errorText');
      _safeNotify();
      return null;
    } finally {
      isCreatingJob = false;
      _safeNotify();
    }
  }

  Future<Map<String, dynamic>?> runAnalysisJob({
    // 0.5 = one analyzed frame every 2 seconds.
    // For server CPU this is much faster and still enough for first AI overview.
    double samplingFps = 0.5,
    double maxMinutes = 2.0,
  }) async {
    if (!hasJob || jobId == null || jobId!.isEmpty) return null;

    isStartingRun = true;
    errorText = null;
    _safeNotify();

    try {
      debugPrint(
        '🚀 runAnalysisJob params: samplingFps=$samplingFps, maxMinutes=$maxMinutes, jobId=$jobId',
      );

      final result = await service.runJob(
        jobId!,
        samplingFps: samplingFps,
        maxMinutes: maxMinutes,
      );

      return result;
    } catch (e) {
      errorText = e.toString();
      debugPrint('❌ runAnalysisJob error: $errorText');
      return null;
    } finally {
      isStartingRun = false;
      _safeNotify();
    }
  }

  Future<AiJobStatusResponse?> refreshStatus() async {
    if (!hasJob) return null;

    try {
      final status = await service.getJobStatus(jobId!);
      jobStatus = status;
      errorText = null;
      debugPrint('🔄 Status refreshed: ${status.status}');
      _safeNotify();
      return status;
    } catch (e) {
      errorText = e.toString();
      debugPrint('❌ Failed to refresh status: $errorText');
      _safeNotify();
      return null;
    }
  }

  Future<Map<String, dynamic>?> loadJobStatus() async {
    if (!hasJob) return null;

    try {
      final result = await service.getJobStatusRaw(jobId!);
      if (result == null) return null;
      errorText = null;
      _safeNotify();
      return Map<String, dynamic>.from(result);
    } catch (e) {
      errorText = e.toString();
      debugPrint('❌ Failed to load job status raw: $errorText');
      _safeNotify();
      return null;
    }
  }

  Future<bool> waitUntilDone({
    Duration interval = const Duration(seconds: 2),
    Duration timeout = const Duration(minutes: 5),
    bool skipStatusCheck = false,
  }) async {
    if (!hasJob) {
      debugPrint('❌ No job ID available');
      return false;
    }

    if (skipStatusCheck) {
      debugPrint(
        '⏳ Skipping status check, waiting ${timeout.inSeconds} seconds...',
      );
      await Future.delayed(timeout);
      return true;
    }

    isPollingStatus = true;
    errorText = null;
    _safeNotify();

    try {
      debugPrint('⏳ Starting waitUntilDone for job: $jobId');

      final status = await service.pollUntilDone(
        jobId!,
        interval: interval,
        timeout: timeout,
        onProgress: (value) {
          jobStatus = value;
          debugPrint('📊 Progress update: ${value.status}');
          _safeNotify();
        },
      );

      jobStatus = status;
      debugPrint('🏁 Final status: ${status.status}');

      if (status.isFailed) {
        errorText = status.error ?? 'AI анализ завершился с ошибкой';
        debugPrint('❌ Analysis failed: $errorText');
        _safeNotify();
        return false;
      }

      debugPrint('✅ Analysis completed successfully!');
      return status.isDone;
    } catch (e) {
      errorText = e.toString();
      debugPrint('❌ waitUntilDone error: $errorText');
      _safeNotify();
      return false;
    } finally {
      isPollingStatus = false;
      _safeNotify();
    }
  }

  Future<AiFramePacket?> loadFramePacket(int timeMs) async {
    if (!hasJob) {
      debugPrint('❌ No job ID for frame packet');
      return null;
    }

    isLoadingFrame = true;
    errorText = null;
    _safeNotify();

    try {
      debugPrint('📸 Loading frame packet for job: $jobId at ${timeMs}ms');

      final packet = await service.getFramePacket(
        jobId: jobId!,
        timeMs: timeMs,
      );

      currentFramePacket = packet;
      _lastRequestedTimeMs = timeMs;
      debugPrint('✅ Frame packet loaded: ${packet.tracks.length} tracks');
      _safeNotify();
      return packet;
    } catch (e) {
      errorText = e.toString();
      debugPrint('❌ Failed to load frame packet: $errorText');
      _safeNotify();
      return null;
    } finally {
      isLoadingFrame = false;
      _safeNotify();
    }
  }

  void loadFramePacketDebounced(
    int timeMs, {
    Duration delay = const Duration(milliseconds: 260),
  }) {
    if (!hasJob) return;

    if ((timeMs - _lastRequestedTimeMs).abs() < 250) {
      return;
    }

    _frameDebounce?.cancel();
    _frameDebounce = Timer(delay, () {
      unawaited(loadFramePacket(timeMs));
    });
  }

  Future<bool> submitCalibration(List<AiCalibrationPoint> points) async {
    if (!hasJob) return false;

    isSendingCalibration = true;
    errorText = null;
    _safeNotify();

    try {
      await service.sendCalibration(
        jobId: jobId!,
        points: points,
      );
      debugPrint('✅ Calibration sent successfully');
      return true;
    } catch (e) {
      errorText = e.toString();
      debugPrint('❌ Failed to send calibration: $errorText');
      _safeNotify();
      return false;
    } finally {
      isSendingCalibration = false;
      _safeNotify();
    }
  }

  Future<AiPlayerSummary?> loadPlayerSummary(String trackId) async {
    if (!hasJob) return null;

    isLoadingSummary = true;
    errorText = null;
    _safeNotify();

    try {
      final summary = await service.getPlayerSummary(
        jobId: jobId!,
        trackId: trackId,
      );

      currentPlayerSummary = summary;
      debugPrint('✅ Player summary loaded for track: $trackId');
      _safeNotify();
      return summary;
    } catch (e) {
      errorText = e.toString();
      debugPrint('❌ Failed to load player summary: $errorText');
      _safeNotify();
      return null;
    } finally {
      isLoadingSummary = false;
      _safeNotify();
    }
  }

  void clearSession() {
    _frameDebounce?.cancel();
    _frameDebounce = null;

    jobId = null;
    jobStatus = null;
    currentFramePacket = null;
    currentPlayerSummary = null;
    errorText = null;
    _lastRequestedTimeMs = -1;

    debugPrint('🧹 Session cleared');
    _safeNotify();
  }

  @override
  void dispose() {
    _disposed = true;
    _frameDebounce?.cancel();
    super.dispose();
  }
}



// ============================================================================
// BEGIN INLINE: multi_player_tracking_controller.dart
// ============================================================================

class MultiPlayerTrackingController extends ChangeNotifier {
  final List<PlayerTrack> _activeTracks = [];
  final List<PlayerTrack> _archivedTracks = [];

  List<PlayerTrack> get activeTracks => List.unmodifiable(_activeTracks);
  List<PlayerTrack> get archivedTracks => List.unmodifiable(_archivedTracks);

  int _nextStableTrackId = 1;

  double pixelsToMeters = 0.12;

  int maxMissedFrames = 10;
  int maxPointsPerTrack = 180;

  double maxMatchDistancePx = 160.0;
  double minIoUForBonus = 0.10;
  double maxSpeedKmh = 42.0;

  double positionSmoothFactor = 0.82;
  double speedSmoothFactor = 0.72;

  final Map<String, int> _missedFramesByTrackId = {};

  void reset() {
    _activeTracks.clear();
    _archivedTracks.clear();
    _missedFramesByTrackId.clear();
    _nextStableTrackId = 1;
    notifyListeners();
  }

  void calibratePixelsToMeters(double value) {
    if (value > 0) {
      pixelsToMeters = value;
      notifyListeners();
    }
  }

  void updateTracks({
    required List<DetectedPlayerBox> detections,
    required int timeMs,
  }) {
    if (_activeTracks.isEmpty) {
      _bootstrapTracks(detections, timeMs);
      notifyListeners();
      return;
    }

    final unmatchedDetections = List<DetectedPlayerBox>.from(detections);
    final matchedTrackIds = <String>{};

    final sortedTracks = List<PlayerTrack>.from(_activeTracks)
      ..sort((a, b) {
        final aSeen = a.lastSeenTimeMs;
        final bSeen = b.lastSeenTimeMs;
        return bSeen.compareTo(aSeen);
      });

    for (final track in sortedTracks) {
      final match = _findBestDetectionForTrack(track, unmatchedDetections);

      if (match == null) {
        _missedFramesByTrackId[track.id] =
            (_missedFramesByTrackId[track.id] ?? 0) + 1;
        continue;
      }

      unmatchedDetections.remove(match);

      final updated = _updateTrackFromDetection(
        track: track,
        detection: match,
        timeMs: timeMs,
      );

      final index = _activeTracks.indexWhere((t) => t.id == track.id);
      if (index != -1) {
        _activeTracks[index] = updated;
      }

      _missedFramesByTrackId[track.id] = 0;
      matchedTrackIds.add(track.id);
    }

    for (final detection in unmatchedDetections) {
      final newTrack = _createTrackFromDetection(detection, timeMs);
      _activeTracks.add(newTrack);
      _missedFramesByTrackId[newTrack.id] = 0;
    }

    _archiveLostTracks();
    notifyListeners();
  }

  PlayerTrack? findTrackByStableId(int stableTrackId) {
    for (final track in _activeTracks) {
      final parsed = _stableIdOfTrack(track);
      if (parsed == stableTrackId) return track;
    }
    for (final track in _archivedTracks) {
      final parsed = _stableIdOfTrack(track);
      if (parsed == stableTrackId) return track;
    }
    return null;
  }

  PlayerTrack? findNearestTrack(Offset position) {
    if (_activeTracks.isEmpty) return null;

    PlayerTrack? best;
    double bestDistance = double.infinity;

    for (final track in _activeTracks) {
      final current = track.currentPosition;
      if (current == null) continue;

      final distance = (current - position).distance;
      if (distance < bestDistance) {
        bestDistance = distance;
        best = track;
      }
    }

    return best;
  }

  Map<String, dynamic> exportJson() {
    return {
      'active_tracks': _activeTracks.map((e) => e.toJson()).toList(),
      'archived_tracks': _archivedTracks.map((e) => e.toJson()).toList(),
      'pixels_to_meters': pixelsToMeters,
    };
  }

  void _bootstrapTracks(List<DetectedPlayerBox> detections, int timeMs) {
    for (final detection in detections) {
      final track = _createTrackFromDetection(detection, timeMs);
      _activeTracks.add(track);
      _missedFramesByTrackId[track.id] = 0;
    }
  }

  PlayerTrack _createTrackFromDetection(
    DetectedPlayerBox detection,
    int timeMs,
  ) {
    final stableId = _nextStableTrackId++;
    final trackId = 'multi_track_$stableId';

    return PlayerTrack(
      id: trackId,
      boundPlayerName: 'Игрок $stableId',
      color: _colorForStableId(stableId),
      points: [
        TrackPoint(
          position: detection.rect.center,
          timeMs: timeMs,
          speed: 0,
          vx: 0,
          vy: 0,
          ax: 0,
          ay: 0,
          rect: detection.rect,
        ),
      ],
      createdAtMs: timeMs,
      lastSeenTimeMs: timeMs,
      speed: 0,
      lockedBox: detection.rect,
    );
  }

  DetectedPlayerBox? _findBestDetectionForTrack(
    PlayerTrack track,
    List<DetectedPlayerBox> detections,
  ) {
    if (detections.isEmpty) return null;
    if (track.points.isEmpty) return null;

    final currentRect = track.currentBoundingBox;
    final currentPos = track.currentPosition;
    if (currentRect == null || currentPos == null) return null;

    DetectedPlayerBox? best;
    double bestScore = double.infinity;

    for (final detection in detections) {
      final distance = (detection.rect.center - currentPos).distance;
      if (distance > maxMatchDistancePx) continue;

      final iou = _computeIoU(currentRect, detection.rect);
      final sizePenalty = _sizePenalty(currentRect, detection.rect);

      double score = distance + sizePenalty * 55.0;

      if (iou >= minIoUForBonus) {
        score -= iou * 35.0;
      }

      if (score < bestScore) {
        bestScore = score;
        best = detection;
      }
    }

    return best;
  }

  PlayerTrack _updateTrackFromDetection({
    required PlayerTrack track,
    required DetectedPlayerBox detection,
    required int timeMs,
  }) {
    final previousPoint = track.points.isNotEmpty ? track.points.last : null;
    final previousRect = track.currentBoundingBox ?? detection.rect;

    final smoothedRect = _smoothRect(previousRect, detection.rect, positionSmoothFactor);
    final newCenter = smoothedRect.center;

    double vx = 0;
    double vy = 0;
    double ax = 0;
    double ay = 0;
    double speedKmh = 0;

    if (previousPoint != null) {
      final dt = ((timeMs - previousPoint.timeMs) / 1000.0).clamp(0.01, 0.25);

      final rawVx = (newCenter.dx - previousPoint.position.dx) / dt;
      final rawVy = (newCenter.dy - previousPoint.position.dy) / dt;

      vx = previousPoint.vx * (1 - speedSmoothFactor) + rawVx * speedSmoothFactor;
      vy = previousPoint.vy * (1 - speedSmoothFactor) + rawVy * speedSmoothFactor;

      ax = (vx - previousPoint.vx) / dt;
      ay = (vy - previousPoint.vy) / dt;

      final distancePx =
          sqrt(pow(newCenter.dx - previousPoint.position.dx, 2) +
              pow(newCenter.dy - previousPoint.position.dy, 2));

      final distanceM = distancePx * pixelsToMeters;
      speedKmh = (distanceM / dt) * 3.6;

      if (speedKmh > maxSpeedKmh) {
        speedKmh = previousPoint.speed;
      }
    }

    final newPoint = TrackPoint(
      position: newCenter,
      timeMs: timeMs,
      speed: speedKmh,
      vx: vx,
      vy: vy,
      ax: ax,
      ay: ay,
      rect: smoothedRect,
    );

    final updatedPoints = List<TrackPoint>.from(track.points)..add(newPoint);

    final trimmedPoints = updatedPoints.length > maxPointsPerTrack
        ? updatedPoints.sublist(updatedPoints.length - maxPointsPerTrack)
        : updatedPoints;

    return track.copyWith(
      points: trimmedPoints,
      speed: speedKmh,
      lastSeenTimeMs: timeMs,
      lockedBox: smoothedRect,
    );
  }

  void _archiveLostTracks() {
    final lost = <PlayerTrack>[];

    for (final track in _activeTracks) {
      final missed = _missedFramesByTrackId[track.id] ?? 0;
      if (missed > maxMissedFrames) {
        lost.add(track);
      }
    }

    for (final track in lost) {
      _activeTracks.removeWhere((t) => t.id == track.id);
      _missedFramesByTrackId.remove(track.id);
      _archivedTracks.add(track);
    }
  }

  int _stableIdOfTrack(PlayerTrack track) {
    final id = track.id;
    if (id.startsWith('multi_track_')) {
      return int.tryParse(id.replaceFirst('multi_track_', '')) ?? 0;
    }
    return 0;
  }

  Rect _smoothRect(Rect prev, Rect next, double t) {
    return Rect.fromLTRB(
      prev.left * (1 - t) + next.left * t,
      prev.top * (1 - t) + next.top * t,
      prev.right * (1 - t) + next.right * t,
      prev.bottom * (1 - t) + next.bottom * t,
    );
  }

  double _sizePenalty(Rect a, Rect b) {
    final areaA = a.width * a.height;
    final areaB = b.width * b.height;
    if (areaA <= 0) return 0;
    return ((areaB - areaA).abs() / areaA);
  }

  double _computeIoU(Rect a, Rect b) {
    final left = max(a.left, b.left);
    final top = max(a.top, b.top);
    final right = min(a.right, b.right);
    final bottom = min(a.bottom, b.bottom);

    if (right <= left || bottom <= top) return 0.0;

    final intersection = (right - left) * (bottom - top);
    final union = a.width * a.height + b.width * b.height - intersection;
    if (union <= 0) return 0.0;

    return intersection / union;
  }

  Color _colorForStableId(int stableId) {
    final colors = <Color>[
      const Color(0xFF2563EB),
      const Color(0xFFDC2626),
      const Color(0xFF16A34A),
      const Color(0xFFF59E0B),
      const Color(0xFF7C3AED),
      const Color(0xFF0891B2),
      const Color(0xFFEA580C),
      const Color(0xFFBE123C),
      const Color(0xFF4F46E5),
      const Color(0xFF0F766E),
    ];

    return colors[(stableId - 1) % colors.length];
  }
}



// ============================================================================
// BEGIN INLINE: python_tracking_service.dart
// ============================================================================

class PythonTrackingResult {
  final List<DetectedPlayerBox> detections;
  final Rect? ballRect;
  final double? ballConfidence;
  final double? frameWidth;
  final double? frameHeight;

  const PythonTrackingResult({
    required this.detections,
    this.ballRect,
    this.ballConfidence,
    this.frameWidth,
    this.frameHeight,
  });

  bool get hasBall => ballRect != null;

  factory PythonTrackingResult.empty() {
    return const PythonTrackingResult(
      detections: [],
      ballRect: null,
      ballConfidence: null,
      frameWidth: null,
      frameHeight: null,
    );
  }
}

class PythonTrackingService {
  final String baseUrl;

  PythonTrackingService({required this.baseUrl});

  Future<PythonTrackingResult> detectFrame({
    required File frameFile,
    required int timeMs,
  }) async {
    try {
      final url = '$baseUrl/analyze_frame';
      debugPrint('🚀 PYTHON URL: $url');
      debugPrint('🕒 timeMs: $timeMs');
      debugPrint('🖼 frame path: ${frameFile.path}');

      final request = http.MultipartRequest(
        'POST',
        Uri.parse(url),
      );

      request.fields['timeMs'] = timeMs.toString();
      request.files.add(
        await http.MultipartFile.fromPath(
          'frame',
          frameFile.path,
        ),
      );

      final streamed = await request.send().timeout(
        const Duration(seconds: 20),
      );

      final response = await http.Response.fromStream(streamed).timeout(
        const Duration(seconds: 20),
      );

      debugPrint('📥 PYTHON STATUS: ${response.statusCode}');
      debugPrint('📥 PYTHON BODY: ${response.body}');

      if (response.statusCode != 200) {
        return PythonTrackingResult.empty();
      }

      final data = jsonDecode(response.body) as Map<String, dynamic>;

      if (data['success'] != true) {
        debugPrint('❌ PYTHON success=false: ${data['error']}');
        return PythonTrackingResult.empty();
      }

      return _parseTrackingResult(data);
    } catch (e) {
      debugPrint('❌ PYTHON detectFrame error: $e');
      return PythonTrackingResult.empty();
    }
  }

  Future<PythonTrackingResult> detectFrameFromUrl({
    required String videoUrl,
    required int timeMs,
  }) async {
    try {
      final url = '$baseUrl/analyze_frame_from_url';
      debugPrint('🚀 PYTHON URL STREAM: $url');
      debugPrint('🎬 videoUrl: $videoUrl');
      debugPrint('🕒 timeMs: $timeMs');

      final response = await http
          .post(
            Uri.parse(url),
            headers: {
              'Content-Type': 'application/json',
            },
            body: jsonEncode({
              'video_url': videoUrl,
              'timeMs': timeMs,
            }),
          )
          .timeout(const Duration(seconds: 25));

      debugPrint('📥 PYTHON STREAM STATUS: ${response.statusCode}');
      debugPrint('📥 PYTHON STREAM BODY: ${response.body}');

      if (response.statusCode != 200) {
        return PythonTrackingResult.empty();
      }

      final data = jsonDecode(response.body) as Map<String, dynamic>;

      if (data['success'] != true) {
        debugPrint('❌ PYTHON STREAM success=false: ${data['error']}');
        return PythonTrackingResult.empty();
      }

      return _parseTrackingResult(data);
    } catch (e) {
      debugPrint('❌ PYTHON detectFrameFromUrl error: $e');
      return PythonTrackingResult.empty();
    }
  }

  PythonTrackingResult _parseTrackingResult(Map<String, dynamic> data) {
    final detectionsRaw = (data['detections'] as List?) ?? const [];

    final detections = detectionsRaw
        .map(
          (item) => DetectedPlayerBox.fromJson(
            Map<String, dynamic>.from(item as Map),
          ),
        )
        .toList();

    Rect? ballRect;
    double? ballConfidence;

    final rawBall = data['ball'];
    if (rawBall is Map) {
      final ballMap = Map<String, dynamic>.from(rawBall);

      final left = (ballMap['left'] ?? ballMap['x'] ?? 0).toDouble();
      final top = (ballMap['top'] ?? ballMap['y'] ?? 0).toDouble();

      final right = ballMap['right'] != null
          ? (ballMap['right']).toDouble()
          : left + (ballMap['width'] ?? 0).toDouble();

      final bottom = ballMap['bottom'] != null
          ? (ballMap['bottom']).toDouble()
          : top + (ballMap['height'] ?? 0).toDouble();

      if (right > left && bottom > top) {
        ballRect = Rect.fromLTRB(left, top, right, bottom);
        ballConfidence = (ballMap['confidence'] ?? 0).toDouble();
      }
    }

    final frameWidth = (data['frame_width'] as num?)?.toDouble();
    final frameHeight = (data['frame_height'] as num?)?.toDouble();

    return PythonTrackingResult(
      detections: detections,
      ballRect: ballRect,
      ballConfidence: ballConfidence,
      frameWidth: frameWidth,
      frameHeight: frameHeight,
    );
  }
}



// ============================================================================
// BEGIN INLINE: tracking_analytics_service.dart
// ============================================================================

class TrackingAnalyticsService {
  static TrackingStats compute(List<TrackPoint> pts) {
    if (pts.isEmpty || pts.length < 2) {
      return const TrackingStats.empty();
    }

    double totalDistance = 0;
    double maxSpeed = 0;
    double totalSpeed = 0;

    for (int i = 1; i < pts.length; i++) {
      totalDistance += (pts[i].position - pts[i - 1].position).distance;
    }

    for (final p in pts) {
      totalSpeed += p.speed;
      if (p.speed > maxSpeed) {
        maxSpeed = p.speed;
      }
    }

    final durationMs = pts.last.timeMs - pts.first.timeMs;
    final averageSpeed = pts.isEmpty ? 0.0 : totalSpeed / pts.length;

    return TrackingStats(
      totalDistance: totalDistance.toDouble(),
      averageSpeed: averageSpeed.toDouble(),
      maxSpeed: maxSpeed.toDouble(),
      durationMs: durationMs,
    );
  }
}



