// ============================================================================
// BEGIN INLINE: painters/tactical_annotation_painter.dart
// ============================================================================

class TacticalAnnotationPainter extends CustomPainter {
  final List<TacticalAnnotation> items;
  final String? selectedId;

  const TacticalAnnotationPainter({
    required this.items,
    this.selectedId,
  });

  Offset _scalePoint(Offset p, Size size) {
    return Offset(p.dx * size.width, p.dy * size.height);
  }

  Paint _basePaint(TacticalAnnotation item) {
    return Paint()
      ..color = item.color.withOpacity(item.opacity)
      ..strokeWidth = item.strokeWidth
      ..style = item.filled ? PaintingStyle.fill : PaintingStyle.stroke
      ..strokeCap = StrokeCap.round
      ..strokeJoin = StrokeJoin.round;
  }

  void _drawDashedLine(Canvas canvas, Offset start, Offset end, Paint paint) {
    const dashWidth = 10.0;
    const dashSpace = 7.0;

    final dx = end.dx - start.dx;
    final dy = end.dy - start.dy;
    final distance = math.sqrt(dx * dx + dy * dy);

    if (distance <= 0) return;

    final vx = dx / distance;
    final vy = dy / distance;

    double drawn = 0;
    while (drawn < distance) {
      final x1 = start.dx + vx * drawn;
      final y1 = start.dy + vy * drawn;
      final next = math.min(drawn + dashWidth, distance);
      final x2 = start.dx + vx * next;
      final y2 = start.dy + vy * next;
      canvas.drawLine(Offset(x1, y1), Offset(x2, y2), paint);
      drawn += dashWidth + dashSpace;
    }
  }

  void _drawArrow(Canvas canvas, Offset start, Offset end, Paint paint) {
    canvas.drawLine(start, end, paint);

    final angle = math.atan2(end.dy - start.dy, end.dx - start.dx);
    final wing = 16.0 + paint.strokeWidth;
    final wingAngle = math.pi / 7;

    final p1 = Offset(
      end.dx - wing * math.cos(angle - wingAngle),
      end.dy - wing * math.sin(angle - wingAngle),
    );

    final p2 = Offset(
      end.dx - wing * math.cos(angle + wingAngle),
      end.dy - wing * math.sin(angle + wingAngle),
    );

    canvas.drawLine(end, p1, paint);
    canvas.drawLine(end, p2, paint);
  }

  void _drawRunArrow(Canvas canvas, Offset start, Offset end, Paint paint) {
    final curvedPaint = Paint()
      ..color = paint.color
      ..strokeWidth = paint.strokeWidth
      ..style = PaintingStyle.stroke
      ..strokeCap = StrokeCap.round
      ..strokeJoin = StrokeJoin.round;

    final mid = Offset(
      (start.dx + end.dx) / 2,
      (start.dy + end.dy) / 2 - 36,
    );

    final path = Path()
      ..moveTo(start.dx, start.dy)
      ..quadraticBezierTo(mid.dx, mid.dy, end.dx, end.dy);

    if (paint.color.opacity > 0) {
      if (paint.strokeWidth > 0) {
        if (paint.style == PaintingStyle.stroke) {
          canvas.drawPath(path, curvedPaint);
        }
      }
    }

    final tangentStart = Offset(
      end.dx - mid.dx,
      end.dy - mid.dy,
    );
    final angle = math.atan2(tangentStart.dy, tangentStart.dx);
    final wing = 16.0 + paint.strokeWidth;
    final wingAngle = math.pi / 7;

    final p1 = Offset(
      end.dx - wing * math.cos(angle - wingAngle),
      end.dy - wing * math.sin(angle - wingAngle),
    );
    final p2 = Offset(
      end.dx - wing * math.cos(angle + wingAngle),
      end.dy - wing * math.sin(angle + wingAngle),
    );

    canvas.drawLine(end, p1, curvedPaint);
    canvas.drawLine(end, p2, curvedPaint);
  }

  void _drawPlayerMarker(
    Canvas canvas,
    Size size,
    TacticalAnnotation item,
    Paint paint,
  ) {
    final pos = item.start != null
        ? _scalePoint(item.start!, size)
        : (item.textOffset != null ? _scalePoint(item.textOffset!, size) : null);
    if (pos == null) return;

    final fillPaint = Paint()
      ..color = item.color.withOpacity(0.18)
      ..style = PaintingStyle.fill;

    canvas.drawCircle(pos, 20, fillPaint);
    canvas.drawCircle(
      pos,
      20,
      Paint()
        ..color = item.color.withOpacity(item.opacity)
        ..style = PaintingStyle.stroke
        ..strokeWidth = item.strokeWidth,
    );

    final text = item.text?.trim().isNotEmpty == true ? item.text!.trim() : 'P';

    final tp = TextPainter(
      text: TextSpan(
        text: text,
        style: TextStyle(
          color: item.color,
          fontSize: 14,
          fontWeight: FontWeight.w900,
        ),
      ),
      textDirection: TextDirection.ltr,
    )..layout();

    tp.paint(
      canvas,
      Offset(
        pos.dx - tp.width / 2,
        pos.dy - tp.height / 2,
      ),
    );
  }

  void _drawFreePath(Canvas canvas, Size size, TacticalAnnotation item, Paint paint) {
    final pts = item.points;
    if (pts == null || pts.length < 2) return;

    final path = Path();
    final first = _scalePoint(pts.first, size);
    path.moveTo(first.dx, first.dy);

    for (final p in pts.skip(1)) {
      final pp = _scalePoint(p, size);
      path.lineTo(pp.dx, pp.dy);
    }

    canvas.drawPath(path, paint);
  }

  void _drawText(Canvas canvas, Size size, TacticalAnnotation item) {
    if (item.text == null || item.textOffset == null) return;

    final pos = _scalePoint(item.textOffset!, size);

    final tp = TextPainter(
      text: TextSpan(
        text: item.text!,
        style: TextStyle(
          color: item.color.withOpacity(item.opacity),
          fontSize: item.fontSize ?? 18,
          fontWeight: FontWeight.w900,
          shadows: const [
            Shadow(
              blurRadius: 4,
              color: Colors.black26,
              offset: Offset(0, 1),
            ),
          ],
        ),
      ),
      textDirection: TextDirection.ltr,
    )..layout(maxWidth: size.width * 0.6);

    tp.paint(canvas, pos);
  }

  void _drawSelection(Canvas canvas, Size size, TacticalAnnotation item) {
    if (item.id != selectedId) return;

    final highlightPaint = Paint()
      ..color = const Color(0xFF2563EB).withOpacity(0.9)
      ..strokeWidth = 2
      ..style = PaintingStyle.stroke;

    Rect? bounds;

    if (item.start != null && item.end != null) {
      bounds = Rect.fromPoints(
        _scalePoint(item.start!, size),
        _scalePoint(item.end!, size),
      );
    } else if (item.points != null && item.points!.isNotEmpty) {
      final scaled = item.points!.map((p) => _scalePoint(p, size)).toList();
      double minX = scaled.first.dx;
      double maxX = scaled.first.dx;
      double minY = scaled.first.dy;
      double maxY = scaled.first.dy;

      for (final p in scaled) {
        minX = math.min(minX, p.dx);
        maxX = math.max(maxX, p.dx);
        minY = math.min(minY, p.dy);
        maxY = math.max(maxY, p.dy);
      }
      bounds = Rect.fromLTRB(minX, minY, maxX, maxY);
    } else if (item.textOffset != null) {
      final pos = _scalePoint(item.textOffset!, size);
      bounds = Rect.fromLTWH(pos.dx - 6, pos.dy - 6, 110, 36);
    }

    if (bounds == null) return;

    final padded = bounds.inflate(8);
    _drawDashedLine(canvas, padded.topLeft, padded.topRight, highlightPaint);
    _drawDashedLine(canvas, padded.topRight, padded.bottomRight, highlightPaint);
    _drawDashedLine(canvas, padded.bottomRight, padded.bottomLeft, highlightPaint);
    _drawDashedLine(canvas, padded.bottomLeft, padded.topLeft, highlightPaint);
  }

  @override
  void paint(Canvas canvas, Size size) {
    for (final item in items) {
      final paint = _basePaint(item);

      switch (item.type) {
        case TacticalToolType.passArrow:
          if (item.start != null && item.end != null) {
            final s = _scalePoint(item.start!, size);
            final e = _scalePoint(item.end!, size);
            _drawArrow(canvas, s, e, paint);
          }
          break;

        case TacticalToolType.runArrow:
          if (item.start != null && item.end != null) {
            final s = _scalePoint(item.start!, size);
            final e = _scalePoint(item.end!, size);
            _drawRunArrow(canvas, s, e, paint);
          }
          break;

        case TacticalToolType.straightLine:
          if (item.start != null && item.end != null) {
            final s = _scalePoint(item.start!, size);
            final e = _scalePoint(item.end!, size);
            canvas.drawLine(s, e, paint);
          }
          break;

        case TacticalToolType.dashedLine:
          if (item.start != null && item.end != null) {
            final s = _scalePoint(item.start!, size);
            final e = _scalePoint(item.end!, size);
            _drawDashedLine(canvas, s, e, paint);
          }
          break;

        case TacticalToolType.circle:
          if (item.start != null && item.end != null) {
            final rect = Rect.fromPoints(
              _scalePoint(item.start!, size),
              _scalePoint(item.end!, size),
            );
            canvas.drawOval(rect, paint);
          }
          break;

        case TacticalToolType.rect:
        case TacticalToolType.zone:
          if (item.start != null && item.end != null) {
            final rect = Rect.fromPoints(
              _scalePoint(item.start!, size),
              _scalePoint(item.end!, size),
            );
            canvas.drawRect(rect, paint);
          }
          break;

        case TacticalToolType.playerMarker:
          _drawPlayerMarker(canvas, size, item, paint);
          break;

        case TacticalToolType.text:
          _drawText(canvas, size, item);
          break;

        case TacticalToolType.freeDraw:
          _drawFreePath(canvas, size, item, paint);
          break;

        case TacticalToolType.select:
        case TacticalToolType.eraser:
          break;
      }

      _drawSelection(canvas, size, item);
    }
  }

  @override
  bool shouldRepaint(covariant TacticalAnnotationPainter oldDelegate) {
    return oldDelegate.items != items || oldDelegate.selectedId != selectedId;
  }
}



// ============================================================================
// BEGIN INLINE: player_tracking_painter.dart
// ============================================================================

class PlayerTrackingPainter extends CustomPainter {
  final AiTrackingController controller;
  final int currentTimeMs;
  final Size fieldSize;

  /// Размер координат, в которых приходят AI bbox/points.
  /// Например: 640x360 для analysis-space. Painter сам переводит их
  /// в реальный прямоугольник видео внутри BoxFit.contain, чтобы рамки
  /// не уезжали в чёрные полосы и не пропадали за пределами кадра.
  final Size? sourceSize;
  final BoxFit fit;

  PlayerTrackingPainter({
    required this.controller,
    required this.currentTimeMs,
    required this.fieldSize,
    this.sourceSize,
    this.fit = BoxFit.contain,
  }) : super(repaint: controller);

  @override
  void paint(Canvas canvas, Size size) {
    final src = sourceSize;
    if (src != null && src.width > 0 && src.height > 0) {
      final videoRect = _fittedVideoRect(
        sourceSize: src,
        targetSize: size,
        fit: fit,
      );

      canvas.save();
      canvas.clipRect(videoRect);
      canvas.translate(videoRect.left, videoRect.top);
      canvas.scale(videoRect.width / src.width, videoRect.height / src.height);
      _paintContent(canvas, src);
      canvas.restore();
      return;
    }

    _paintContent(canvas, size);
  }

  void _paintContent(Canvas canvas, Size size) {
    _drawDangerZones(canvas, size);
    _drawTeamShapes(canvas);

    for (final track in controller.tracks) {
      final isSelected = controller.selectedTrackId == track.id;

      if (controller.showOnlySelectedPlayer && !isSelected) {
        continue;
      }

      _drawTrail(canvas, track, isSelected);
    }

    _drawPassArrows(canvas);
    _drawBall(canvas);

    for (final track in controller.tracks) {
      final isSelected = controller.selectedTrackId == track.id;

      if (controller.showOnlySelectedPlayer && !isSelected) {
        continue;
      }

      _drawBoundingBox(canvas, track, isSelected);
      _drawLabel(canvas, track, isSelected);
      _drawSpeed(canvas, track, isSelected);
      _drawPredictedRect(canvas, track, isSelected);
    }
  }

  Rect _fittedVideoRect({
    required Size sourceSize,
    required Size targetSize,
    required BoxFit fit,
  }) {
    final sourceAspect = sourceSize.width / sourceSize.height;
    final targetAspect = targetSize.width / targetSize.height;

    double drawWidth;
    double drawHeight;

    if (fit == BoxFit.cover) {
      if (sourceAspect > targetAspect) {
        drawHeight = targetSize.height;
        drawWidth = drawHeight * sourceAspect;
      } else {
        drawWidth = targetSize.width;
        drawHeight = drawWidth / sourceAspect;
      }
    } else {
      if (sourceAspect > targetAspect) {
        drawWidth = targetSize.width;
        drawHeight = drawWidth / sourceAspect;
      } else {
        drawHeight = targetSize.height;
        drawWidth = drawHeight * sourceAspect;
      }
    }

    final dx = (targetSize.width - drawWidth) / 2;
    final dy = (targetSize.height - drawHeight) / 2;
    return Rect.fromLTWH(dx, dy, drawWidth, drawHeight);
  }

  void _drawTrail(Canvas canvas, PlayerTrack track, bool isSelected) {
    if (!controller.showTrails || track.points.length < 2) return;

    for (int i = 1; i < track.points.length; i++) {
      final p1 = track.points[i - 1].position;
      final p2 = track.points[i].position;
      final t = i / track.points.length;

      final glowPaint = Paint()
        ..color = track.color.withOpacity((0.10 + 0.18 * t).clamp(0.0, 1.0))
        ..strokeWidth = 4 + 2 * t
        ..strokeCap = StrokeCap.round
        ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 4);

      final linePaint = Paint()
        ..color = track.color.withOpacity((0.28 + 0.72 * t).clamp(0.0, 1.0))
        ..strokeWidth = (isSelected ? 2.8 : 1.8) + 1.8 * t
        ..strokeCap = StrokeCap.round;

      canvas.drawLine(p1, p2, glowPaint);
      canvas.drawLine(p1, p2, linePaint);
    }

    final currentDotPaint = Paint()..color = track.color;
    canvas.drawCircle(
      track.points.last.position,
      isSelected ? 5.5 : 4.0,
      currentDotPaint,
    );
  }

  void _drawBoundingBox(Canvas canvas, PlayerTrack track, bool isSelected) {
    if (!controller.showBoundingBoxes) return;

    final rect = track.currentBoundingBox;
    if (rect == null) return;

    final strokePaint = Paint()
      ..color = track.color
      ..style = PaintingStyle.stroke
      ..strokeWidth = isSelected ? 2.8 : 2.0;

    final glowPaint = Paint()
      ..color = track.color.withOpacity(0.12)
      ..style = PaintingStyle.fill;

    canvas.drawRRect(
      RRect.fromRectAndRadius(rect, const Radius.circular(8)),
      glowPaint,
    );
    canvas.drawRRect(
      RRect.fromRectAndRadius(rect, const Radius.circular(8)),
      strokePaint,
    );
  }

  void _drawLabel(Canvas canvas, PlayerTrack track, bool isSelected) {
    if (!controller.showLabels) return;

    final rect = track.currentBoundingBox;
    if (rect == null) return;

    final label = (track.boundPlayerName.isNotEmpty
            ? track.boundPlayerName
            : track.id)
        .trim();

    final textPainter = TextPainter(
      text: TextSpan(
        text: label,
        style: TextStyle(
          color: Colors.white,
          fontSize: isSelected ? 12 : 11,
          fontWeight: FontWeight.w800,
        ),
      ),
      textDirection: TextDirection.ltr,
      maxLines: 1,
      ellipsis: '…',
    )..layout(maxWidth: 160);

    final bgRect = RRect.fromRectAndRadius(
      Rect.fromLTWH(
        rect.left,
        math.max(0, rect.top - 22),
        textPainter.width + 12,
        18,
      ),
      const Radius.circular(6),
    );

    final bgPaint = Paint()..color = track.color.withOpacity(0.92);

    canvas.drawRRect(bgRect, bgPaint);
    textPainter.paint(canvas, Offset(bgRect.left + 6, bgRect.top + 2));
  }

  void _drawSpeed(Canvas canvas, PlayerTrack track, bool isSelected) {
    if (!controller.showSpeed || track.points.isEmpty) return;

    final rect = track.currentBoundingBox;
    if (rect == null) return;

    final speedText = '${track.points.last.speed.toStringAsFixed(1)} км/ч';

    final textPainter = TextPainter(
      text: TextSpan(
        text: speedText,
        style: const TextStyle(
          color: Colors.white,
          fontSize: 10,
          fontWeight: FontWeight.w700,
        ),
      ),
      textDirection: TextDirection.ltr,
      maxLines: 1,
    )..layout();

    final bgRect = RRect.fromRectAndRadius(
      Rect.fromLTWH(
        rect.left,
        rect.bottom + 4,
        textPainter.width + 10,
        16,
      ),
      const Radius.circular(6),
    );

    final bgPaint = Paint()..color = Colors.black.withOpacity(0.65);

    canvas.drawRRect(bgRect, bgPaint);
    textPainter.paint(canvas, Offset(bgRect.left + 5, bgRect.top + 2));
  }

  void _drawPredictedRect(Canvas canvas, PlayerTrack track, bool isSelected) {
    if (!isSelected) return;

    final predicted = controller.getPredictedRectForTrack(track, currentTimeMs);
    if (predicted == null) return;

    final paint = Paint()
      ..color = track.color.withOpacity(0.45)
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1.5;

    _drawDashedRRect(
      canvas,
      RRect.fromRectAndRadius(predicted, const Radius.circular(8)),
      paint,
    );
  }

  void _drawDashedRRect(Canvas canvas, RRect rrect, Paint paint) {
    final rect = rrect.outerRect;
    const dash = 7.0;
    const gap = 4.0;

    void drawDashedLine(Offset a, Offset b) {
      final dx = b.dx - a.dx;
      final dy = b.dy - a.dy;
      final distance = math.sqrt(dx * dx + dy * dy);
      if (distance == 0) return;

      final ux = dx / distance;
      final uy = dy / distance;

      double start = 0;
      while (start < distance) {
        final end = math.min(start + dash, distance);
        final p1 = Offset(a.dx + ux * start, a.dy + uy * start);
        final p2 = Offset(a.dx + ux * end, a.dy + uy * end);
        canvas.drawLine(p1, p2, paint);
        start += dash + gap;
      }
    }

    drawDashedLine(rect.topLeft, rect.topRight);
    drawDashedLine(rect.topRight, rect.bottomRight);
    drawDashedLine(rect.bottomRight, rect.bottomLeft);
    drawDashedLine(rect.bottomLeft, rect.topLeft);
  }

  void _drawBall(Canvas canvas) {
    if (!controller.showBall) return;

    final ballTrack = controller.ballTrack;
    final ball = ballTrack?.lastPoint;
    if (ball == null) return;

    if (controller.showBallTrail && ballTrack!.points.length > 1) {
      for (int i = 1; i < ballTrack.points.length; i++) {
        final p1 = ballTrack.points[i - 1].position;
        final p2 = ballTrack.points[i].position;
        final t = i / ballTrack.points.length;

        final paint = Paint()
          ..color = Colors.white.withOpacity((0.15 + 0.55 * t).clamp(0.0, 1.0))
          ..strokeWidth = 1.2 + 1.2 * t
          ..strokeCap = StrokeCap.round;

        canvas.drawLine(p1, p2, paint);
      }
    }

    final glow = Paint()
      ..color = const Color(0xFFFFF59D).withOpacity(0.30)
      ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 8);

    final fill = Paint()..color = Colors.white;
    final ring = Paint()
      ..color = Colors.black.withOpacity(0.55)
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1.2;

    canvas.drawCircle(ball.position, 10, glow);
    canvas.drawCircle(ball.position, 5, fill);
    canvas.drawCircle(ball.position, 5, ring);
  }

  void _drawPassArrows(Canvas canvas) {
    if (!controller.showPassNetwork && controller.passArrows.isEmpty) return;

    for (final arrow in controller.passArrows) {
      final age = currentTimeMs - arrow.timeMs;
      if (age > 3500) continue;

      final alpha = 1.0 - (age / 3500).clamp(0, 1);
      final color =
          const Color(0xFF38BDF8).withOpacity((0.20 + 0.70 * alpha).clamp(0.0, 1.0));

      final paint = Paint()
        ..color = color
        ..strokeWidth = 3
        ..strokeCap = StrokeCap.round;

      canvas.drawLine(arrow.from, arrow.to, paint);

      final dir = arrow.to - arrow.from;
      final len = dir.distance;
      if (len > 0) {
        final n = Offset(dir.dx / len, dir.dy / len);
        final left = Offset(-n.dy, n.dx);

        final tip = arrow.to;
        final wing1 = tip - n * 14 + left * 7;
        final wing2 = tip - n * 14 - left * 7;

        canvas.drawLine(tip, wing1, paint);
        canvas.drawLine(tip, wing2, paint);
      }
    }
  }

  void _drawDangerZones(Canvas canvas, Size size) {
    final finalThird = Rect.fromLTWH(
      size.width * 0.75,
      0,
      size.width * 0.25,
      size.height,
    );

    final paint = Paint()
      ..color = const Color(0xFFEF4444).withOpacity(0.05);

    canvas.drawRect(finalThird, paint);
  }

  void _drawTeamShapes(Canvas canvas) {
    _drawTeamShape(canvas, _getTeamShapeRect('home'), const Color(0xFF2563EB));
    _drawTeamShape(canvas, _getTeamShapeRect('away'), const Color(0xFFDC2626));
  }

  Rect? _getTeamShapeRect(String teamTag) {
    final teamTracks = controller.tracks.where((t) => t.teamTag == teamTag).toList();
    if (teamTracks.length < 2) return null;

    final positions = teamTracks
        .map((t) => t.currentPosition)
        .whereType<Offset>()
        .toList();

    if (positions.length < 2) return null;

    final minX = positions.map((e) => e.dx).reduce(math.min);
    final maxX = positions.map((e) => e.dx).reduce(math.max);
    final minY = positions.map((e) => e.dy).reduce(math.min);
    final maxY = positions.map((e) => e.dy).reduce(math.max);

    return Rect.fromLTRB(minX, minY, maxX, maxY);
  }

  void _drawTeamShape(Canvas canvas, Rect? rect, Color color) {
    if (rect == null) return;

    final expanded = rect.inflate(18);

    final fill = Paint()
      ..color = color.withOpacity(0.05)
      ..style = PaintingStyle.fill;

    final stroke = Paint()
      ..color = color.withOpacity(0.22)
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1.5;

    final rrect = RRect.fromRectAndRadius(expanded, const Radius.circular(22));

    canvas.drawRRect(rrect, fill);
    canvas.drawRRect(rrect, stroke);
  }

  @override
  bool shouldRepaint(covariant PlayerTrackingPainter oldDelegate) {
    return oldDelegate.currentTimeMs != currentTimeMs ||
        oldDelegate.fieldSize != fieldSize ||
        oldDelegate.sourceSize != sourceSize ||
        oldDelegate.fit != fit ||
        oldDelegate.controller != controller;
  }
}



