                  )
                : ListView.builder(
                    padding: const EdgeInsets.all(12),
                    itemCount: episodes.length,
                    itemBuilder: (context, index) {
                      final episode = episodes[index];
                      return _buildEpisodeCard(
                        Map<String, dynamic>.from(episode),
                      );
                    },
                  ),
          ),
        ],
      ),
    );
  }
}



