      decoration: _cmrPanelDecoration(radius: 14, elevated: true),
      child: Row(
        children: [
          Container(
            width: 42,
            height: 42,
            decoration: BoxDecoration(
              color: _cmrPanel,
              borderRadius: BorderRadius.circular(11),
              border: Border.all(color: color.withOpacity(.32), width: 1),
            ),
            child: Icon(icon, color: color, size: 21),
          ),
          const SizedBox(width: 12),
          Expanded(
            child: Column(
              mainAxisAlignment: MainAxisAlignment.center,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  title,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: _cmrMutedStyle(11.5, color: _cmrMuted2, weight: FontWeight.w600),
                ),
                const SizedBox(height: 5),
                Row(
                  children: [
                    Flexible(child: Text(value, style: _cmrTitle(21), maxLines: 1, overflow: TextOverflow.ellipsis)),
                    const SizedBox(width: 8),
                    Container(
                      width: 6,
                      height: 6,
                      decoration: BoxDecoration(color: color, shape: BoxShape.circle),
