// BEGIN INLINE: screens/episode_annotation_model.dart
// ============================================================================

enum AnnotationToolType {
  freehand,
  line,
  arrow,
  rect,
  circle,
  text,
}

class AnnotationItem {
  final String id;
  final AnnotationToolType type;
  final Color color;
  final double strokeWidth;

  final Offset? start;
  final Offset? end;

  final List<Offset>? points;

  final String? text;
  final double? fontSize;
  final Offset? textOffset;

  AnnotationItem({
    required this.id,
    required this.type,
    required this.color,
    required this.strokeWidth,
    this.start,
    this.end,
    this.points,
    this.text,
    this.fontSize,
    this.textOffset,
  });

  Map<String, dynamic> toJson() {
    return {
      'id': id,
      'type': type.name,
      'color': color.value,
      'strokeWidth': strokeWidth,
      'startX': start?.dx,
      'startY': start?.dy,
      'endX': end?.dx,
      'endY': end?.dy,
      'points': points
          ?.map((p) => {
                'x': p.dx,
                'y': p.dy,
              })
          .toList(),
      'text': text,
      'fontSize': fontSize,
      'textX': textOffset?.dx,
      'textY': textOffset?.dy,
    };
  }

  factory AnnotationItem.fromJson(Map<String, dynamic> json) {
    return AnnotationItem(
      id: (json['id'] ?? '').toString(),
      type: AnnotationToolType.values.firstWhere(
        (e) => e.name == json['type'],
        orElse: () => AnnotationToolType.line,
      ),
      color: Color((json['color'] as num?)?.toInt() ?? Colors.red.value),
      strokeWidth: (json['strokeWidth'] as num?)?.toDouble() ?? 3.0,
      start: (json['startX'] != null && json['startY'] != null)
          ? Offset(
              (json['startX'] as num).toDouble(),
              (json['startY'] as num).toDouble(),
            )
          : null,
      end: (json['endX'] != null && json['endY'] != null)
          ? Offset(
              (json['endX'] as num).toDouble(),
              (json['endY'] as num).toDouble(),
            )
          : null,
      points: (json['points'] as List?)
          ?.map((e) => Offset(
                (e['x'] as num).toDouble(),
                (e['y'] as num).toDouble(),
              ))
          .toList(),
      text: json['text']?.toString(),
      fontSize: (json['fontSize'] as num?)?.toDouble(),
      textOffset: (json['textX'] != null && json['textY'] != null)
          ? Offset(
              (json['textX'] as num).toDouble(),
              (json['textY'] as num).toDouble(),
            )
          : null,
    );
  }

  static String encodeList(List<AnnotationItem> items) {
    return jsonEncode(items.map((e) => e.toJson()).toList());
  }

  static List<AnnotationItem> decodeList(String raw) {
    final list = jsonDecode(raw) as List;
    return list.map((e) => AnnotationItem.fromJson(Map<String, dynamic>.from(e))).toList();
  }
}



// ============================================================================
// BEGIN INLINE: screens/episode_annotation_painter.dart
// ============================================================================

class EpisodeAnnotationPainter extends CustomPainter {
  final List<AnnotationItem> items;
  final Size originalSize;

  EpisodeAnnotationPainter({
    required this.items,
    required this.originalSize,
  });

  Offset _scalePoint(Offset p, Size size) {
    return Offset(p.dx * size.width, p.dy * size.height);
  }

  @override
  void paint(Canvas canvas, Size size) {
    for (final item in items) {
      final paint = Paint()
        ..color = item.color
        ..strokeWidth = item.strokeWidth
        ..style = PaintingStyle.stroke
        ..strokeCap = StrokeCap.round
        ..strokeJoin = StrokeJoin.round;

      switch (item.type) {
        case AnnotationToolType.line:
          if (item.start != null && item.end != null) {
            canvas.drawLine(
              _scalePoint(item.start!, size),
              _scalePoint(item.end!, size),
              paint,
            );
          }
          break;

        case AnnotationToolType.arrow:
          if (item.start != null && item.end != null) {
            final start = _scalePoint(item.start!, size);
            final end = _scalePoint(item.end!, size);
            canvas.drawLine(start, end, paint);

            final angle = math.atan2(end.dy - start.dy, end.dx - start.dx);
            const arrowSize = 14.0;

            final path = Path()
              ..moveTo(end.dx, end.dy)
              ..lineTo(
                end.dx - arrowSize * math.cos(angle - math.pi / 6),
                end.dy - arrowSize * math.sin(angle - math.pi / 6),
              )
              ..moveTo(end.dx, end.dy)
              ..lineTo(
                end.dx - arrowSize * math.cos(angle + math.pi / 6),
                end.dy - arrowSize * math.sin(angle + math.pi / 6),
              );

            canvas.drawPath(path, paint);
          }
          break;

        case AnnotationToolType.rect:
          if (item.start != null && item.end != null) {
            final rect = Rect.fromPoints(
              _scalePoint(item.start!, size),
              _scalePoint(item.end!, size),
            );
            canvas.drawRect(rect, paint);
          }
          break;

        case AnnotationToolType.circle:
          if (item.start != null && item.end != null) {
            final rect = Rect.fromPoints(
              _scalePoint(item.start!, size),
              _scalePoint(item.end!, size),
            );
            canvas.drawOval(rect, paint);
          }
          break;

        case AnnotationToolType.freehand:
          final pts = item.points;
          if (pts != null && pts.length > 1) {
            final path = Path()..moveTo(
              _scalePoint(pts.first, size).dx,
              _scalePoint(pts.first, size).dy,
            );
            for (final p in pts.skip(1)) {
              final pp = _scalePoint(p, size);
              path.lineTo(pp.dx, pp.dy);
            }
            canvas.drawPath(path, paint);
          }
          break;

        case AnnotationToolType.text:
          if (item.text != null && item.textOffset != null) {
            final tp = TextPainter(
              text: TextSpan(
                text: item.text!,
                style: TextStyle(
                  color: item.color,
                  fontSize: item.fontSize ?? 18,
                  fontWeight: FontWeight.w800,
                ),
              ),
              textDirection: TextDirection.ltr,
            )..layout();
            tp.paint(canvas, _scalePoint(item.textOffset!, size));
          }
          break;
      }
    }
  }

  @override
  bool shouldRepaint(covariant EpisodeAnnotationPainter oldDelegate) {
    return oldDelegate.items != items;
  }
}



// ============================================================================
// BEGIN INLINE: screens/episode_annotation_editor_screen.dart
// ============================================================================

class EpisodeAnnotationEditorScreen extends StatefulWidget {
  final int episodeId;
  final int coachId;
  final String imageUrl;

  const EpisodeAnnotationEditorScreen({
    super.key,
    required this.episodeId,
    required this.coachId,
    required this.imageUrl,
  });

  @override
  State<EpisodeAnnotationEditorScreen> createState() =>
      _EpisodeAnnotationEditorScreenState();
}

class _EpisodeAnnotationEditorScreenState
    extends State<EpisodeAnnotationEditorScreen> {
  final TextEditingController _textCtrl = TextEditingController();
  final TextEditingController _playerMarkerCtrl = TextEditingController();

  List<TacticalAnnotation> _items = [];
  TacticalAnnotation? _draft;
  String? _selectedId;

  final List<List<TacticalAnnotation>> _undoStack = [];
  final List<List<TacticalAnnotation>> _redoStack = [];

  TacticalToolType _tool = TacticalToolType.freeDraw;
  Color _selectedColor = const Color(0xFFEF4444);
  double _strokeWidth = 4.0;
  double _opacity = 1.0;
  bool _zoneFilled = true;

  bool _loading = true;
  bool _saving = false;
  String? _message;
  bool _messageError = false;

  Size? _imageNaturalSize;
  bool _imageInfoLoading = true;
  bool _imageLoadError = false;

  String _s(dynamic v) => (v ?? '').toString().trim();

  @override
  void initState() {
    super.initState();
    _loadAnnotations();
    _loadImageInfo();
  }

  @override
  void dispose() {
    _textCtrl.dispose();
    _playerMarkerCtrl.dispose();
    super.dispose();
  }

  Future<void> _loadImageInfo() async {
    if (widget.imageUrl.isEmpty) {
      setState(() {
        _imageLoadError = true;
        _imageInfoLoading = false;
      });
      return;
    }

    setState(() {
      _imageInfoLoading = true;
      _imageLoadError = false;
    });

    try {
      final imageProvider = NetworkImage(widget.imageUrl);
      final stream = imageProvider.resolve(const ImageConfiguration());

      final listener = ImageStreamListener(
        (ImageInfo info, bool _) {
          if (!mounted) return;
          setState(() {
            _imageNaturalSize = Size(
              info.image.width.toDouble(),
              info.image.height.toDouble(),
            );
            _imageInfoLoading = false;
            _imageLoadError = false;
          });
        },
        onError: (error, stackTrace) {
          if (!mounted) return;
          setState(() {
            _imageNaturalSize = null;
            _imageInfoLoading = false;
            _imageLoadError = true;
          });
          _showMessage('Ошибка загрузки изображения', isError: true);
        },
      );

      stream.addListener(listener);
    } catch (_) {
      if (!mounted) return;
      setState(() {
        _imageInfoLoading = false;
        _imageLoadError = true;
      });
      _showMessage('Ошибка загрузки изображения', isError: true);
    }
  }

  void _showMessage(String text, {bool isError = false}) {
    setState(() {
      _message = text;
      _messageError = isError;
    });

    Future.delayed(const Duration(seconds: 3), () {
      if (!mounted) return;
      if (_message == text) {
        setState(() => _message = null);
      }
    });
  }

  Map<String, dynamic> _safeDecode(String body) {
    try {
      final decoded = jsonDecode(body);
      if (decoded is Map<String, dynamic>) return decoded;
      return {
        'success': false,
        'message': 'Некорректный JSON-ответ',
      };
    } catch (e) {
      return {
        'success': false,
        'message': 'Ошибка JSON: $e',
      };
    }
  }

  List<TacticalAnnotation> _cloneItems(List<TacticalAnnotation> source) {
    return source
        .map((e) =>
            TacticalAnnotation.fromJson(Map<String, dynamic>.from(e.toJson())))
        .toList();
  }

  void _pushUndoState() {
    _undoStack.add(_cloneItems(_items));
    _redoStack.clear();
  }

  void _undo() {
    if (_undoStack.isEmpty) return;
    _redoStack.add(_cloneItems(_items));
    setState(() {
      _items = _undoStack.removeLast();
      _selectedId = null;
    });
  }

  void _redo() {
    if (_redoStack.isEmpty) return;
    _undoStack.add(_cloneItems(_items));
    setState(() {
      _items = _redoStack.removeLast();
      _selectedId = null;
    });
  }

  Future<void> _loadAnnotations() async {
    try {
      final uri = Uri.parse(
        '${ApiConstants.apiBase}/get_episode_annotations.php?episode_id=${widget.episodeId}',
      );

      final res = await http.get(uri);
      final body = utf8.decode(res.bodyBytes, allowMalformed: true).trim();
      final data = _safeDecode(body);

      if (data['success'] == true) {
        final annotation = data['annotation'];
        String raw = '';

        if (annotation is Map && annotation['annotations_json'] != null) {
          raw = annotation['annotations_json'].toString();
        } else if (data['annotations_json'] != null) {
          raw = data['annotations_json'].toString();
        }

        setState(() {
          _items = TacticalAnnotation.decodeList(raw);
        });
      } else {
        _showMessage(
          _s(data['message']).isNotEmpty
              ? _s(data['message'])
              : 'Не удалось загрузить разметку',
          isError: true,
        );
      }
    } catch (e) {
      _showMessage('Ошибка загрузки: $e', isError: true);
    } finally {
      if (mounted) {
        setState(() => _loading = false);
      }
    }
  }

  Future<void> _saveAnnotations() async {
    setState(() => _saving = true);

    try {
      final response = await http.post(
        Uri.parse('${ApiConstants.apiBase}/save_episode_annotations.php'),
        body: {
          'episode_id': widget.episodeId.toString(),
          'coach_id': widget.coachId.toString(),
          'image_url': widget.imageUrl,
          'annotations_json': TacticalAnnotation.encodeList(_items),
        },
      );

      final body = utf8.decode(response.bodyBytes, allowMalformed: true).trim();
      final data = _safeDecode(body);

      if (data['success'] == true) {
        _showMessage('Разметка сохранена');
      } else {
        _showMessage(
          _s(data['message']).isNotEmpty
              ? _s(data['message'])
              : 'Ошибка сохранения',
          isError: true,
        );
      }
    } catch (e) {
      _showMessage('Сетевая ошибка: $e', isError: true);
    } finally {
      if (mounted) {
        setState(() => _saving = false);
      }
    }
  }

  Offset _normalizeOffset(Offset local, Size size) {
    return Offset(
      (local.dx / size.width).clamp(0.0, 1.0),
      (local.dy / size.height).clamp(0.0, 1.0),
    );
  }

  Rect _scaledRectFromAnnotation(TacticalAnnotation item, Size size) {
    if (item.start != null && item.end != null) {
      final a =
          Offset(item.start!.dx * size.width, item.start!.dy * size.height);
      final b = Offset(item.end!.dx * size.width, item.end!.dy * size.height);
      return Rect.fromPoints(a, b);
    }

    if (item.textOffset != null) {
      final p = Offset(
        item.textOffset!.dx * size.width,
        item.textOffset!.dy * size.height,
      );
      return Rect.fromLTWH(p.dx - 8, p.dy - 8, 140, 42);
    }

    if (item.points != null && item.points!.isNotEmpty) {
      final scaled = item.points!
          .map((p) => Offset(p.dx * size.width, p.dy * size.height))
          .toList();

      double minX = scaled.first.dx;
      double maxX = scaled.first.dx;
      double minY = scaled.first.dy;
      double maxY = scaled.first.dy;

      for (final p in scaled) {
        if (p.dx < minX) minX = p.dx;
        if (p.dx > maxX) maxX = p.dx;
        if (p.dy < minY) minY = p.dy;
        if (p.dy > maxY) maxY = p.dy;
      }

      return Rect.fromLTRB(minX, minY, maxX, maxY);
    }

    return Rect.zero;
  }

  String? _hitTestAnnotation(Offset local, Size size) {
    for (int i = _items.length - 1; i >= 0; i--) {
      final item = _items[i];
      final rect = _scaledRectFromAnnotation(item, size).inflate(22);
      if (rect.contains(local)) {
        return item.id;
      }
    }
    return null;
  }

