    return LayoutBuilder(
      builder: (context, constraints) {
        if (constraints.maxHeight <= 0) {
          return Container(
            color: Colors.white,
            child: const Center(
              child: Text(
                'Waiting for layout...',
                style: TextStyle(color: Colors.black, fontSize: 16),
              ),
            ),
          );
        }

        if (_imageInfoLoading) {
          return Container(
            color: Colors.white,
            child: const Center(
              child: CircularProgressIndicator(),
            ),
          );
        }

        if (_imageLoadError || _imageNaturalSize == null) {
          return Container(
            color: Colors.white,
            child: Center(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  const Text(
                    'Error loading image',
                    style: TextStyle(color: Colors.black, fontSize: 18),
                  ),
                  const SizedBox(height: 8),
                  Padding(
                    padding: const EdgeInsets.symmetric(horizontal: 16),
                    child: SelectableText(
                      widget.imageUrl,
                      textAlign: TextAlign.center,
                      style:
                          const TextStyle(color: Colors.black54, fontSize: 10),
                    ),
                  ),
                  const SizedBox(height: 16),
                  ElevatedButton(
                    onPressed: _loadImageInfo,
                    child: const Text('Retry'),
                  ),
                ],
              ),
            ),
          );
        }

        final imageAspect = _imageNaturalSize!.width / _imageNaturalSize!.height;
        final maxWidth = constraints.maxWidth;
        final maxHeight = constraints.maxHeight;

        final double effectiveHeight = maxHeight > 0 ? maxHeight : 400.0;
        final double effectiveWidth = maxWidth > 0 ? maxWidth : 400.0;

        double drawWidth = effectiveWidth;
        double drawHeight = drawWidth / imageAspect;

        if (drawHeight > effectiveHeight) {
          drawHeight = effectiveHeight;
          drawWidth = drawHeight * imageAspect;
        }

        final drawSize = Size(drawWidth, drawHeight);

        return Container(
          color: Colors.white,
          alignment: Alignment.center,
          child: SizedBox(
            width: drawWidth,
            height: drawHeight,
            child: GestureDetector(
              onPanStart: (d) => _onPanStart(d, drawSize),
              onPanUpdate: (d) => _onPanUpdate(d, drawSize),
              onPanEnd: _onPanEnd,
              child: Stack(
                fit: StackFit.expand,
                children: [
                  Image.network(
                    widget.imageUrl,
                    fit: BoxFit.fill,
                    loadingBuilder: (context, child, loadingProgress) {
                      if (loadingProgress == null) return child;
                      return const Center(child: CircularProgressIndicator());
                    },
                    errorBuilder: (context, error, stackTrace) {
                      return Container(
                        color: const Color(0xFFF3F4F6),
                        child: const Center(
                          child: Text(
                            'Image load error',
                            style: TextStyle(color: Colors.black),
                          ),
                        ),
                      );
                    },
                  ),
                  Positioned.fill(
                    child: CustomPaint(
                      painter: TacticalAnnotationPainter(
                        items: [..._items, if (_draft != null) _draft!],
                        selectedId: _selectedId,
                      ),
                    ),
                  ),
                ],
              ),
            ),
          ),
        );
      },
    );
  }

  Widget _desktopCanvasLayout() {
    return SafeArea(
      child: Column(
        children: [
          _topHeader(),
          Expanded(
            child: Row(
              children: [
                const SizedBox(width: 12),
                _leftToolsPanel(),
                const SizedBox(width: 12),
                Expanded(
                  child: Padding(
                    padding: const EdgeInsets.symmetric(vertical: 12),
                    child: _canvasCenter(),
                  ),
                ),
                const SizedBox(width: 12),
                _rightPropertiesPanel(),
                const SizedBox(width: 12),
              ],
            ),
          ),
        ],
      ),
    );
  }

  Widget _mobileBottomToolbar() {
    final tools = [
      TacticalToolType.select,
      TacticalToolType.passArrow,
      TacticalToolType.runArrow,
      TacticalToolType.circle,
      TacticalToolType.zone,
      TacticalToolType.text,
      TacticalToolType.freeDraw,
      TacticalToolType.eraser,
    ];

    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 10),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(18),
        border: Border.all(color: const Color(0xFFE5E7EB)),
      ),
      child: SizedBox(
        height: 72,
        child: ListView.separated(
          scrollDirection: Axis.horizontal,
          itemCount: tools.length,
          separatorBuilder: (_, __) => const SizedBox(width: 10),
          itemBuilder: (context, index) => _toolButton(tools[index]),
        ),
      ),
    );
  }

  Widget _mobilePropertiesCard() {
    final hasSelected = _selectedId != null;

    return Container(
      padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(18),
        border: Border.all(color: const Color(0xFFE5E7EB)),
      ),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            hasSelected ? 'Свойства объекта' : 'Свойства инструмента',
            style: const TextStyle(
              color: Color(0xFF111827),
              fontWeight: FontWeight.w900,
              fontSize: 15,
            ),
          ),
          const SizedBox(height: 10),
          Wrap(
            spacing: 12,
            runSpacing: 12,
            children: [
              _colorDot(const Color(0xFFEF4444)),
              _colorDot(const Color(0xFF2563EB)),
              _colorDot(const Color(0xFF16A34A)),
              _colorDot(const Color(0xFFF59E0B)),
              _colorDot(Colors.white),
              _colorDot(Colors.black),
            ],
          ),
          const SizedBox(height: 12),
          const Text(
            'Толщина',
            style: TextStyle(
              color: Color(0xFF111827),
              fontWeight: FontWeight.w800,
            ),
          ),
          SliderTheme(
            data: SliderTheme.of(context).copyWith(
              activeTrackColor: const Color(0xFF2563EB),
              inactiveTrackColor: const Color(0xFFE5E7EB),
              thumbColor: const Color(0xFF2563EB),
            ),
            child: Slider(
              value: _strokeWidth,
              min: 2,
              max: 10,
              divisions: 8,
              onChanged: (v) {
                setState(() => _strokeWidth = v);
                _updateSelectedStyle();
              },
            ),
          ),
          const Text(
            'Прозрачность',
            style: TextStyle(
              color: Color(0xFF111827),
              fontWeight: FontWeight.w800,
            ),
          ),
          SliderTheme(
            data: SliderTheme.of(context).copyWith(
              activeTrackColor: const Color(0xFF2563EB),
              inactiveTrackColor: const Color(0xFFE5E7EB),
              thumbColor: const Color(0xFF2563EB),
            ),
            child: Slider(
              value: _opacity,
              min: 0.2,
              max: 1.0,
              divisions: 8,
              onChanged: (v) {
                setState(() => _opacity = v);
                _updateSelectedStyle();
              },
            ),
          ),
          Row(
            children: [
              const Expanded(
                child: Text(
                  'Заливка зоны',
                  style: TextStyle(
                    color: Color(0xFF111827),
                    fontWeight: FontWeight.w800,
                  ),
                ),
              ),
              Switch(
                value: _zoneFilled,
                activeColor: const Color(0xFF2563EB),
                onChanged: (v) {
                  setState(() => _zoneFilled = v);
                  _updateSelectedStyle();
                },
              ),
            ],
          ),
          if (hasSelected) ...[
            const SizedBox(height: 8),
            SizedBox(
              width: double.infinity,
              child: ElevatedButton.icon(
                onPressed: _deleteSelected,
                icon: const Icon(Icons.delete_outline_rounded),
                label: const Text('Удалить объект'),
                style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFFDC2626),
                  foregroundColor: Colors.white,
                  padding: const EdgeInsets.symmetric(vertical: 14),
                ),
              ),
            ),
          ],
        ],
      ),
    );
  }

  Widget _mobileCanvasLayout() {
    return SafeArea(
      child: Column(
        children: [
          _topHeader(),
          Expanded(
            child: Padding(
              padding: const EdgeInsets.all(12),
              child: _canvasCenter(),
            ),
          ),
          _mobilePropertiesCard(),
          _mobileBottomToolbar(),
        ],
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: Colors.white,
      body: _loading
          ? const Center(child: CircularProgressIndicator())
          : LayoutBuilder(
              builder: (context, constraints) {
                final isWide = constraints.maxWidth >= 900;
                return isWide
                    ? _desktopCanvasLayout()
                    : _mobileCanvasLayout();
              },
            ),
    );
  }
}



