        color: Colors.transparent,
        child: InkWell(
          borderRadius: BorderRadius.circular(22),
          splashColor: metric.color.withOpacity(0.04),
          highlightColor: metric.color.withOpacity(0.02),
          onTap: () {},
          child: Ink(
            padding: const EdgeInsets.all(14),
            decoration: BoxDecoration(
              color: _EpisodeColors.panelSoft,
              borderRadius: BorderRadius.circular(22),
              border: Border.all(
                color: metric.color.withOpacity(0.18),
                width: 1.1,
              ),
            ),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Row(
                  children: [
                    Container(
                      width: 30,
                      height: 30,
                      decoration: BoxDecoration(
                        color: metric.color.withOpacity(0.10),
                        borderRadius: BorderRadius.circular(10),
                      ),
                      child: Icon(
                        metric.singleOnly
                            ? Icons.score_outlined
                            : Icons.sports_soccer_rounded,
                        size: 15,
                        color: metric.color,
                      ),
                    ),
                    const SizedBox(width: 8),
                    Expanded(
                      child: Text(
                        metric.title,
                        style: const TextStyle(
                          fontSize: 12,
                          fontWeight: FontWeight.w800,
                          color: _EpisodeColors.text,
                          height: 1.2,
                        ),
                        maxLines: 2,
                        overflow: TextOverflow.ellipsis,
                      ),
                    ),
                  ],
                ),
                const Spacer(),
                if (metric.singleOnly)
                  _buildGradientActionButton(
                    label: "+1",
                    color: _EpisodeColors.amber,
                    onTap: _quickSaving
                        ? null
                        : () => _saveSingleTtd(
                              metricCode: metric.code,
                              metricTitle: metric.title,
                              value: 1,
                            ),
                    isSingle: true,
                  )
                else
                  Row(
                    children: [
                      Expanded(
                        child: _buildGradientActionButton(
                          label: "+",
                          color: _EpisodeColors.green,
                          onTap: _quickSaving
                              ? null
                              : () => _saveQuickTtd(
                                    metricCode: metric.code,
                                    metricTitle: metric.title,
                                    isSuccess: true,
                                  ),
                        ),
                      ),
                      const SizedBox(width: 8),
                      Expanded(
                        child: _buildGradientActionButton(
                          label: "−",
                          color: _EpisodeColors.red,
                          onTap: _quickSaving
                              ? null
                              : () => _saveQuickTtd(
                                    metricCode: metric.code,
                                    metricTitle: metric.title,
                                    isSuccess: false,
                                  ),
                        ),
                      ),
                    ],
                  ),
              ],
            ),
          ),
        ),
      ),
    ),
  );
}
