  void _openReview(Map<String, dynamic> item) {
    final matchId = int.tryParse(_s(item["id"])) ?? 0;
    final title = _buildMatchTitle(item);
    final videoUrl = _normalizeUrl(_s(item["video_url"])) ?? "";
    final videoId = matchId;

    if (videoUrl.isEmpty) {
      Get.snackbar("Внимание", "Сначала загрузите видео матча");
      return;
    }

    if (videoId <= 0) {
      Get.snackbar("Внимание", "Не найден id матча");
      return;
    }

    Get.to(
      () => VideoMatchReviewScreen(
        matchId: matchId,
        teamId: widget.teamId,
        teamName: _displayTeamName,
        coachId: _coachId,
        matchTitle: title,
        videoUrl: videoUrl,
        videoId: videoId,
      ),
    );
  }

  Future<void> _openTeamMatchLive() async {
    final item = _matches.isEmpty ? <String, dynamic>{} : _matches.first;
    final rawSessions = item['tracker_session_ids'] ??
        item['session_ids'] ??
        item['tracker_session_id'] ??
        const [];
    final sessionValues = rawSessions is List
        ? rawSessions
        : _s(rawSessions).replaceAll(';', ',').split(',');
    final sessionIds = sessionValues
        .map((value) => int.tryParse(_s(value)) ?? 0)
        .where((value) => value > 0)
        .toSet()
        .toList();
    await MatchLiveScreen.open(
      context,
      initialMode: 'live',
      params: {
        'sourceMode': 'live',
        'matchId': int.tryParse(_s(item['id'])) ?? 0,
        'clubId': widget.clubId,
        'teamId': widget.teamId,
        'coachId': _coachId,
        'fieldId': int.tryParse(_s(item['field_id'])) ?? 0,
        'teamName': _displayTeamName,
        'matchTitle': item.isEmpty ? 'Матч онлайн' : _buildMatchTitle(item),
        'videoUrl': _normalizeUrl(_s(item['video_url'])) ?? '',
        'sessionIds': sessionIds,
        'teamColors': {
          'home': _s(item['home_team_color']).isEmpty ? '#00A750' : _s(item['home_team_color']),
          'away': _s(item['away_team_color']).isEmpty ? '#FFFFFF' : _s(item['away_team_color']),
        },
      },
    );
  }

  Future<void> _refreshWorkspace() async {
    await _loadTeamProfile();
    await _loadMatches();
    await _checkPendingUpload();
  }

  int get _readyVideoCount {
    return _matches.where((item) {
      final videoUrl = _normalizeUrl(_s(item["video_url"])) ?? "";
      return videoUrl.isNotEmpty;
    }).length;
  }

  int get _missingVideoCount => max(0, _matches.length - _readyVideoCount);

  String get _sectionTitle {
    switch (_section) {
      case TeamVideoWorkspaceSection.overview:
        return 'Обзор видеоанализа';
      case TeamVideoWorkspaceSection.all:
        return 'Все матчи';
      case TeamVideoWorkspaceSection.ready:
        return 'Матчи с видео';
      case TeamVideoWorkspaceSection.missing:
        return 'Без видео';
    }
  }

  String get _sectionSubtitle {
    switch (_section) {
      case TeamVideoWorkspaceSection.overview:
        return 'Сводка по загруженным видео, готовности разбора и быстрым действиям';
      case TeamVideoWorkspaceSection.all:
        return 'Каталог матчей команды с загрузкой и открытием разбора';
      case TeamVideoWorkspaceSection.ready:
        return 'Матчи, где видео уже прикреплено и доступен разбор';
      case TeamVideoWorkspaceSection.missing:
        return 'Матчи, куда ещё нужно загрузить видео';
    }
  }

  IconData get _sectionIcon {
    switch (_section) {
      case TeamVideoWorkspaceSection.overview:
        return Icons.dashboard_customize_outlined;
      case TeamVideoWorkspaceSection.all:
        return Icons.video_library_outlined;
      case TeamVideoWorkspaceSection.ready:
        return Icons.play_circle_outline_rounded;
      case TeamVideoWorkspaceSection.missing:
        return Icons.cloud_upload_outlined;
    }
  }

  void _setSection(TeamVideoWorkspaceSection section) {
    if (_section == section) return;
    _section = section;
    _applySearch();
  }

