  Widget _activeVideoContent({required bool isTablet}) {
    if (_loading) {
      return const Center(
        child: CircularProgressIndicator(color: FeedPalette.primaryGreen),
      );
    }

    if (_section == TeamVideoWorkspaceSection.overview) {
      return _buildVideoOverview();
    }

    return RefreshIndicator(
      color: FeedPalette.primaryGreen,
      onRefresh: _refreshWorkspace,
      child: ListView(
        padding: const EdgeInsets.only(bottom: 90),
        children: [
          _searchAndToolbar(),
          _sectionLabel(),
          if (_filteredMatches.isEmpty)
            _buildEmpty()
          else if (_view == TeamVideoCatalogView.grid)
            _gridBody(isTablet)
          else
            _listBody(),
        ],
      ),
    );
  }

  Widget _buildVideoOverview() {
    final latestReady = _matches.where((item) {
      final videoUrl = _normalizeUrl(_s(item["video_url"])) ?? "";
      return videoUrl.isNotEmpty;
    }).take(4).toList();

    final missing = _matches.where((item) {
      final videoUrl = _normalizeUrl(_s(item["video_url"])) ?? "";
      return videoUrl.isEmpty;
    }).take(4).toList();

    return RefreshIndicator(
      color: FeedPalette.primaryGreen,
      onRefresh: _refreshWorkspace,
      child: ListView(
        padding: const EdgeInsets.fromLTRB(16, 16, 16, 90),
        children: [
          LayoutBuilder(
            builder: (context, constraints) {
              final narrow = constraints.maxWidth < 760;
              final cards = [
                _videoKpiCard(
                  icon: Icons.sports_soccer_rounded,
                  title: 'Матчи',
                  value: _matches.length.toString(),
                  subtitle: 'в каталоге',
                ),
                _videoKpiCard(
                  icon: Icons.play_circle_outline_rounded,
                  title: 'С видео',
                  value: _readyVideoCount.toString(),
                  subtitle: 'готовы к разбору',
                ),
                _videoKpiCard(
                  icon: Icons.cloud_upload_outlined,
                  title: 'Без видео',
                  value: _missingVideoCount.toString(),
                  subtitle: 'нужно загрузить',
                ),
              ];

              if (narrow) {
                return Column(
                  children: [
                    for (final card in cards) ...[
                      card,
                      const SizedBox(height: 10),
                    ],
                  ],
                );
              }

              return Row(
                children: [
                  for (int i = 0; i < cards.length; i++) ...[
                    Expanded(child: cards[i]),
                    if (i != cards.length - 1) const SizedBox(width: 12),
                  ],
                ],
              );
            },
          ),
          const SizedBox(height: 14),
          _overviewPanel(
            title: 'Последние видео для разбора',
            subtitle: latestReady.isEmpty
                ? 'Пока нет загруженных видео'
                : 'Быстрый вход в разбор матча',
            icon: Icons.movie_creation_outlined,
            child: latestReady.isEmpty
                ? _overviewHint('Загрузите видео к матчу, и оно появится в этом блоке.')
                : Column(
                    children: latestReady.map((item) {
                      return Padding(
                        padding: const EdgeInsets.only(bottom: 10),
                        child: _compactVideoRow(item, hasVideoList: true),
                      );
                    }).toList(),
                  ),
          ),
          const SizedBox(height: 14),
          _overviewPanel(
            title: 'Матчи без видео',
            subtitle: missing.isEmpty
                ? 'Все матчи закрыты видео'
                : 'Нужно прикрепить файл для анализа',
            icon: Icons.cloud_upload_outlined,
            child: missing.isEmpty
                ? _overviewHint('Отлично: у всех матчей уже есть видео.')
                : Column(
                    children: missing.map((item) {
                      return Padding(
                        padding: const EdgeInsets.only(bottom: 10),
                        child: _compactVideoRow(item, hasVideoList: false),
                      );
                    }).toList(),
                  ),
          ),
        ],
      ),
    );
  }

