  Widget _compactVideoRow(Map<String, dynamic> item, {required bool hasVideoList}) {
    final title = _buildMatchTitle(item);
    final date = _s(item["match_date"]);
    final score =
        "${_s(item["our_score"]).isEmpty ? "0" : _s(item["our_score"])}:"
        "${_s(item["opponent_score"]).isEmpty ? "0" : _s(item["opponent_score"])}";

    return Material(
      color: FeedPalette.surface,
      borderRadius: BorderRadius.circular(16),
      child: InkWell(
        borderRadius: BorderRadius.circular(16),
        onTap: hasVideoList ? () => _openReview(item) : () => _showUploadVideoSheet(item),
        child: Container(
          padding: const EdgeInsets.all(11),
          child: Row(
            children: [
              Container(
                width: 38,
                height: 38,
                alignment: Alignment.center,
                decoration: BoxDecoration(
                  color: hasVideoList ? FeedPalette.greenSoft : Colors.white,
                  borderRadius: BorderRadius.circular(14),
                ),
                child: Icon(
                  hasVideoList ? Icons.play_arrow_rounded : Icons.cloud_upload_outlined,
                  color: hasVideoList ? FeedPalette.primaryGreen : FeedPalette.textMuted,
                  size: 21,
                ),
              ),
              const SizedBox(width: 10),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      title,
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: const TextStyle(
                        color: FeedPalette.text,
                        fontSize: 12.2,
                        fontWeight: FontWeight.w600,
                      ),
                    ),
                    const SizedBox(height: 4),
                    Text(
                      [score, if (date.isNotEmpty) date].join(' • '),
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: const TextStyle(
                        color: FeedPalette.textMuted,
                        fontSize: 10.5,
                        fontWeight: FontWeight.w500,
                      ),
                    ),
                  ],
                ),
              ),
              const SizedBox(width: 8),
              Icon(
                hasVideoList ? Icons.chevron_right_rounded : Icons.add_rounded,
                color: FeedPalette.textMuted,
                size: 20,
              ),
            ],
          ),
        ),
      ),
    );
  }

