  Widget _matchTile(Map<String, dynamic> item) {
    final title = _buildMatchTitle(item);
    final opponent = _s(item["opponent"]);
    final competition = _s(item["competition_name"]);
    final date = _s(item["match_date"]);
    final eventType = _eventTypeLabel(_s(item["event_type"]));
    final thumb = _normalizeUrl(_s(item["thumbnail_url"]));
    final videoUrl = _normalizeUrl(_s(item["video_url"])) ?? "";
    final hasVideo = videoUrl.isNotEmpty;

    final score =
        "${_s(item["our_score"]).isEmpty ? "0" : _s(item["our_score"])}:"
        "${_s(item["opponent_score"]).isEmpty ? "0" : _s(item["opponent_score"])}";

    return _MatteSurface(
      onTap: hasVideo ? () => _openReview(item) : null,
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          _MatchThumb(
            thumb: thumb,
            hasVideo: hasVideo,
            width: 108,
            height: 92,
          ),
          const SizedBox(width: 12),
          Expanded(
            child: Padding(
              padding: const EdgeInsets.symmetric(vertical: 2),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Expanded(
                        child: Text(
                          title,
                          maxLines: 2,
                          overflow: TextOverflow.ellipsis,
                          style: const TextStyle(
                            fontWeight: FontWeight.w600,
                            fontSize: 15,
                            color: FeedPalette.text,
                            height: 1.25,
                          ),
                        ),
                      ),
                      const SizedBox(width: 6),
                      _matchMoreButton(item),
                    ],
                  ),
                  const SizedBox(height: 4),
                  Text(
                    "$eventType • Счёт $score",
                    style: const TextStyle(
                      fontSize: 12,
                      fontWeight: FontWeight.w500,
                      color: FeedPalette.textMuted,
                    ),
                  ),
                  if (competition.isNotEmpty) ...[
                    const SizedBox(height: 3),
                    Text(
                      competition,
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: const TextStyle(
                        fontSize: 12,
                        color: FeedPalette.textMuted,
                      ),
                    ),
                  ],
                  if (opponent.isNotEmpty) ...[
                    const SizedBox(height: 3),
                    Text(
                      "Соперник: $opponent",
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: const TextStyle(
                        fontSize: 12,
                        color: FeedPalette.textMuted,
                      ),
                    ),
                  ],
                  if (date.isNotEmpty) ...[
                    const SizedBox(height: 3),
                    Text(
                      date,
                      style: const TextStyle(
                        fontSize: 12,
                        color: Color(0xFF8A94A6),
                      ),
                    ),
                  ],
                  const SizedBox(height: 10),
                  Wrap(
                    spacing: 8,
                    runSpacing: 8,
                    children: [
                      if (hasVideo)
                        _smallActionButton(
                          label: "Разбор",
                          icon: Icons.play_circle_outline,
                          filled: true,
                          onTap: () => _openReview(item),
                        ),
                      if (!hasVideo)
                        _smallActionButton(
                          label: "Загрузить",
                          icon: Icons.cloud_upload_outlined,
                          filled: false,
                          onTap: () => _showUploadVideoSheet(item),
                        ),
                    ],
                  ),
                ],
              ),
            ),
          ),
        ],
      ),
    );
  }

  Widget _smallActionButton({
    required String label,
    required IconData icon,
    required bool filled,
    required VoidCallback onTap,
  }) {
    if (filled) {
      return Container(
        decoration: BoxDecoration(
          gradient: FeedPalette.greenGradient,
          borderRadius: BorderRadius.circular(12),
        ),
        child: ElevatedButton.icon(
          onPressed: onTap,
          icon: Icon(icon, size: 18),
          label: Text(label),
          style: ElevatedButton.styleFrom(
            backgroundColor: Colors.transparent,
            shadowColor: Colors.transparent,
            foregroundColor: Colors.white,
            elevation: 0,
            padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
            shape: RoundedRectangleBorder(
              borderRadius: BorderRadius.circular(12),
            ),
            textStyle: const TextStyle(
              fontWeight: FontWeight.w600,
              fontSize: 12,
            ),
          ),
        ),
      );
    }

    return OutlinedButton.icon(
      onPressed: onTap,
      icon: Icon(icon, size: 18),
      label: Text(label),
      style: OutlinedButton.styleFrom(
        foregroundColor: FeedPalette.text,
        side: const BorderSide(color: FeedPalette.border),
        padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(12),
        ),
        textStyle: const TextStyle(
          fontWeight: FontWeight.w600,
          fontSize: 12,
        ),
      ),
    );
  }

  Widget _matchGridCard(Map<String, dynamic> item) {
    final title = _buildMatchTitle(item);
    final opponent = _s(item["opponent"]);
    final competition = _s(item["competition_name"]);
    final date = _s(item["match_date"]);
    final eventType = _eventTypeLabel(_s(item["event_type"]));
    final thumb = _normalizeUrl(_s(item["thumbnail_url"]));
    final videoUrl = _normalizeUrl(_s(item["video_url"])) ?? "";
    final hasVideo = videoUrl.isNotEmpty;

    final score =
        "${_s(item["our_score"]).isEmpty ? "0" : _s(item["our_score"])}:"
        "${_s(item["opponent_score"]).isEmpty ? "0" : _s(item["opponent_score"])}";

    return _MatteSurface(
      padding: EdgeInsets.zero,
      onTap: hasVideo ? () => _openReview(item) : null,
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          _MatchThumb(
            thumb: thumb,
            hasVideo: hasVideo,
            width: double.infinity,
            height: 140,
            radius: const BorderRadius.vertical(top: Radius.circular(16)),
          ),
          Expanded(
            child: Padding(
              padding: const EdgeInsets.fromLTRB(12, 12, 12, 12),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Expanded(
                        child: Text(
                          title,
                          maxLines: 2,
                          overflow: TextOverflow.ellipsis,
                          style: const TextStyle(
                            fontWeight: FontWeight.w600,
                            fontSize: 14,
                            color: FeedPalette.text,
                            height: 1.25,
                          ),
                        ),
                      ),
                      const SizedBox(width: 6),
                      _matchMoreButton(item),
                    ],
                  ),
                  const SizedBox(height: 6),
                  Text(
                    "$eventType • $score",
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: const TextStyle(
                      fontSize: 12,
                      fontWeight: FontWeight.w600,
                      color: FeedPalette.textMuted,
                    ),
                  ),
                  if (competition.isNotEmpty) ...[
                    const SizedBox(height: 4),
                    Text(
                      competition,
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: const TextStyle(
                        fontSize: 12,
                        color: FeedPalette.textMuted,
                      ),
                    ),
                  ],
                  if (opponent.isNotEmpty) ...[
                    const SizedBox(height: 4),
                    Text(
                      opponent,
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: const TextStyle(
                        fontSize: 12,
                        color: FeedPalette.textMuted,
                      ),
                    ),
                  ],
                  if (date.isNotEmpty) ...[
                    const SizedBox(height: 4),
                    Text(
                      date,
                      style: const TextStyle(
                        fontSize: 12,
                        color: Color(0xFF8A94A6),
                      ),
                    ),
                  ],
                  const Spacer(),
                  SizedBox(
                    width: double.infinity,
                    child: hasVideo
                        ? Container(
                            decoration: BoxDecoration(
                              gradient: FeedPalette.greenGradient,
                              borderRadius: BorderRadius.circular(12),
                            ),
                            child: ElevatedButton.icon(
                              onPressed: () => _openReview(item),
                              icon: const Icon(Icons.play_circle_outline),
                              label: const Text("Открыть"),
                              style: ElevatedButton.styleFrom(
                                backgroundColor: Colors.transparent,
                                shadowColor: Colors.transparent,
                                foregroundColor: Colors.white,
                                elevation: 0,
                                padding:
                                    const EdgeInsets.symmetric(vertical: 12),
                                shape: RoundedRectangleBorder(
                                  borderRadius: BorderRadius.circular(12),
                                ),
                                textStyle: const TextStyle(
                                  fontWeight: FontWeight.w600,
                                ),
                              ),
                            ),
                          )
                        : OutlinedButton.icon(
                            onPressed: () => _showUploadVideoSheet(item),
                            icon: const Icon(Icons.cloud_upload_outlined),
                            label: const Text("Загрузить"),
                            style: OutlinedButton.styleFrom(
                              foregroundColor: FeedPalette.text,
                              side:
                                  const BorderSide(color: FeedPalette.border),
                              padding: const EdgeInsets.symmetric(vertical: 12),
                              shape: RoundedRectangleBorder(
                                borderRadius: BorderRadius.circular(12),
                              ),
                              textStyle: const TextStyle(
                                fontWeight: FontWeight.w600,
                              ),
                            ),
                          ),
                  ),
                ],
              ),
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildEmpty() {
    final isSearching = _searchCtrl.text.trim().isNotEmpty;

    return Padding(
      padding: const EdgeInsets.fromLTRB(16, 8, 16, 24),
      child: Container(
        width: double.infinity,
        padding: const EdgeInsets.all(24),
        decoration: BoxDecoration(
          color: FeedPalette.white,
          borderRadius: BorderRadius.circular(18),
          border: Border.all(color: FeedPalette.border),
        ),
        child: Column(
          children: [
            Container(
              width: 62,
              height: 62,
              decoration: BoxDecoration(
                color: FeedPalette.superLightGreen,
                borderRadius: BorderRadius.circular(18),
              ),
              child: const Icon(
                Icons.video_library_outlined,
                size: 32,
                color: FeedPalette.primaryGreen,
              ),
            ),
            const SizedBox(height: 14),
            Text(
              isSearching ? "Ничего не найдено" : "Пока нет добавленных матчей",
              style: const TextStyle(
                fontSize: 17,
                fontWeight: FontWeight.w600,
                color: FeedPalette.text,
              ),
            ),
            const SizedBox(height: 8),
            Text(
              isSearching
                  ? "Попробуй изменить поисковый запрос"
                  : "Сначала добавь матчи команды в разделе «Матчи», после этого здесь можно будет прикрепить видео и открыть разбор.",
              textAlign: TextAlign.center,
              style: const TextStyle(
                fontSize: 13,
                color: FeedPalette.textMuted,
                height: 1.4,
                fontWeight: FontWeight.w600,
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _listBody() {
    return ListView.separated(
      itemCount: _filteredMatches.length,
      shrinkWrap: true,
      physics: const NeverScrollableScrollPhysics(),
      padding: const EdgeInsets.fromLTRB(16, 0, 16, 24),
      separatorBuilder: (_, __) => const SizedBox(height: 12),
      itemBuilder: (_, i) => _matchTile(_filteredMatches[i]),
    );
  }

  Widget _gridBody(bool isTablet) {
    return Padding(
      padding: const EdgeInsets.fromLTRB(16, 0, 16, 24),
      child: GridView.builder(
        itemCount: _filteredMatches.length,
        shrinkWrap: true,
        physics: const NeverScrollableScrollPhysics(),
        gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
          crossAxisCount: isTablet ? 3 : 2,
          crossAxisSpacing: 12,
          mainAxisSpacing: 12,
          childAspectRatio: isTablet ? 0.82 : 0.76,
        ),
        itemBuilder: (_, i) => _matchGridCard(_filteredMatches[i]),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final width = MediaQuery.of(context).size.width;
    final isPhone = width < 700;
    final isTablet = width >= 900;

    final body = DefaultTextStyle(
      style: AppTypography.custom(
        size: 12,
        weight: FontWeight.w400,
        color: FeedPalette.text,
        height: 1.24,
        letterSpacing: 0,
      ),
      child: FadeTransition(
        opacity: _animationController,
        child: _buildVideoWorkspace(
          isPhone: isPhone,
          isTablet: isTablet,
        ),
      ),
    );

    if (widget.embedded) {
      return body;
    }

    return Scaffold(
      backgroundColor: Colors.white,
      body: body,
    );
  }
}

class _VideoWindowDot extends StatelessWidget {
  final Color color;

  const _VideoWindowDot({required this.color});

  @override
  Widget build(BuildContext context) {
    return Container(
      width: 11,
      height: 11,
      decoration: BoxDecoration(
        color: color,
        shape: BoxShape.circle,
      ),
    );
  }
}

class _MatteSurface extends StatelessWidget {
  final Widget child;
  final EdgeInsetsGeometry padding;
  final VoidCallback? onTap;

  const _MatteSurface({
    required this.child,
    this.padding = const EdgeInsets.all(12),
    this.onTap,
  });

  @override
  Widget build(BuildContext context) {
    final content = Container(
      padding: padding,
      decoration: BoxDecoration(
        color: FeedPalette.surface,
        borderRadius: BorderRadius.circular(10),
      ),
      child: child,
    );

    if (onTap != null) {
      return Material(
        color: Colors.transparent,
        child: InkWell(
          borderRadius: BorderRadius.circular(10),
          onTap: onTap,
          child: content,
        ),
      );
    }

    return content;
  }
}

class _MatchThumb extends StatelessWidget {
  final String? thumb;
  final bool hasVideo;
  final double width;
  final double height;
  final BorderRadius? radius;

  const _MatchThumb({
    required this.thumb,
    required this.hasVideo,
    required this.width,
    required this.height,
    this.radius,
  });

  @override
  Widget build(BuildContext context) {
    return ClipRRect(
      borderRadius: radius ?? BorderRadius.circular(14),
      child: Stack(
        children: [
          SizedBox(
            width: width,
            height: height,
            child: thumb != null && thumb!.isNotEmpty
                ? Image.network(
                    thumb!,
                    fit: BoxFit.cover,
                    errorBuilder: (_, __, ___) => Container(
                      color: const Color(0xFF111827),
                      child: const Center(
                        child: Icon(
                          Icons.sports_soccer_rounded,
                          color: Colors.white,
                          size: 34,
                        ),
                      ),
                    ),
                  )
                : Container(
                    color: const Color(0xFF111827),
                    child: const Center(
                      child: Icon(
                        Icons.sports_soccer_rounded,
                        color: Colors.white,
                        size: 34,
                      ),
                    ),
                  ),
          ),
          Positioned(
            top: 8,
            left: 8,
            child: Container(
              padding: const EdgeInsets.symmetric(
                horizontal: 8,
                vertical: 5,
              ),
              decoration: BoxDecoration(
                color: hasVideo
                    ? Colors.green.withOpacity(0.92)
                    : Colors.orange.withOpacity(0.92),
                borderRadius: BorderRadius.circular(999),
              ),
              child: Text(
                hasVideo ? "Видео" : "Нет видео",
                style: const TextStyle(
                  color: Colors.white,
                  fontSize: 10,
                  fontWeight: FontWeight.w600,
                ),
              ),
            ),
          ),
        ],
      ),
    );
  }
}

class FeedPalette {
  static const primaryGreen = Color(0xFF00A750);
  static const primaryGreenDark = Color(0xFF008C40);
  static const primaryGreenLight = Color(0xFF00C060);

  static const lightGreen = Color(0xFFE8F5E9);
  static const superLightGreen = Color(0xFFF3FAF6);
  static const greenSoft = Color(0xFFF3FAF6);
  static const surface = Color(0xFFF7F8F7);

  static const white = Color(0xFFFFFFFF);
  static const text = Color(0xFF0B0F14);
  static const textMuted = Color(0xFF5F6670);
  static const background = Color(0xFFFFFFFF);
  static const border = Color(0xFFE9ECEA);

  static const greenGradient = LinearGradient(
    colors: [primaryGreen, primaryGreenDark],
    begin: Alignment.topLeft,
    end: Alignment.bottomRight,
  );
  
}


class _VideoT {
  static TextStyle title(double size, {Color color = FeedPalette.text}) =>
      AppTypography.custom(
        size: size,
        weight: FontWeight.w600,
        color: color,
        height: 1.18,
        letterSpacing: 0,
      );

  static TextStyle body(
    double size, {
    Color color = FeedPalette.textMuted,
    FontWeight weight = FontWeight.w400,
  }) =>
      AppTypography.custom(
        size: size,
        weight: weight,
        color: color,
        height: 1.28,
        letterSpacing: 0,
      );

  static TextStyle value(double size, {Color color = FeedPalette.text}) =>
      AppTypography.custom(
        size: size,
        weight: FontWeight.w600,
        color: color,
        height: 1.12,
        letterSpacing: 0,
      );
}

class _VideoGlowDot extends StatelessWidget {
  const _VideoGlowDot({
    this.color = FeedPalette.primaryGreen,
    this.size = 6,
    this.opacity = 1,
    this.halo = true,
  });

  final Color color;
  final double size;
  final double opacity;
  final bool halo;

  @override
  Widget build(BuildContext context) {
    return Opacity(
      opacity: opacity,
      child: Container(
        width: size,
        height: size,
        decoration: BoxDecoration(
          color: color,
          shape: BoxShape.circle,
          boxShadow: halo
              ? [
                  BoxShadow(
                    color: color.withOpacity(.18),
                    blurRadius: size * 1.8,
                    spreadRadius: .2,
                  ),
                ]
              : null,
        ),
      ),
    );
  }
}



