class _MatchTile extends StatelessWidget {
  final String title;
  final String date;
  final String score;
  final String tournament;
  final bool hasVideo;
  final bool active;
  final VoidCallback onTap;
  final bool compact;

  const _MatchTile({
    required this.title,
    required this.date,
    required this.score,
    required this.tournament,
    required this.hasVideo,
    required this.active,
    required this.onTap,
    this.compact = false,
  });

  @override
  Widget build(BuildContext context) {
    final line = [
      date,
      'счёт $score',
      if (tournament.isNotEmpty) tournament,
    ].join('  ·  ');

    return Material(
      color: active ? _C.greenSoft : Colors.transparent,
      borderRadius: BorderRadius.circular(9),
      child: InkWell(
        borderRadius: BorderRadius.circular(9),
        onTap: onTap,
        child: Container(
          constraints: BoxConstraints(minHeight: compact ? 54 : 58),
          padding: EdgeInsets.fromLTRB(
            compact ? 9 : 10,
            compact ? 7 : 8,
            compact ? 8 : 9,
            compact ? 7 : 8,
          ),
          child: Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Padding(
                padding: const EdgeInsets.only(top: 5),
                child: _VideoGlowDot(
                  color: active ? _C.primary : _C.muted,
                  size: active ? 6.2 : 4.8,
                  opacity: active ? 1 : .46,
                  halo: active,
                ),
              ),
              const SizedBox(width: 9),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      title,
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: AppTypography.custom(
                        size: compact ? 10.8 : 11.2,
                        weight: active ? FontWeight.w600 : FontWeight.w500,
                        color: active ? _C.primaryDark : _C.text,
                        height: 1.2,
                        letterSpacing: 0,
                      ),
                    ),
                    const SizedBox(height: 4),
                    Text(
                      line,
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: AppTypography.custom(
                        size: compact ? 9.4 : 9.8,
                        weight: FontWeight.w400,
                        color: active
                            ? _C.primaryDark.withOpacity(.68)
                            : _C.muted,
                        height: 1.2,
                        letterSpacing: 0,
                      ),
                    ),
                  ],
                ),
              ),
              const SizedBox(width: 7),
              Icon(
                hasVideo ? Icons.videocam_rounded : Icons.videocam_off_rounded,
                color: hasVideo
                    ? (active ? _C.primary : _C.primaryDark.withOpacity(.72))
                    : _C.dim,
                size: 16,
              ),
            ],
          ),
        ),
      ),
    );
  }
}

class _ThumbBox extends StatelessWidget {
  final String? url;
  final bool hasVideo;
