void _exportAiAnalysis() {
  _writeAiAnalysisExport();
}

Future<void> _writeAiAnalysisExport() async {
  try {
    final dir = _resolveExportDirectory();
    final stamp = DateTime.now()
        .toIso8601String()
        .replaceAll(':', '-')
        .replaceAll('.', '-');
    final baseName = 'sportoteka_ai_match_${widget.matchId}_$stamp';

    final htmlFile = File('${dir.path}/$baseName.html');
    final csvFile = File('${dir.path}/$baseName.csv');
    final jsonFile = File('${dir.path}/$baseName.json');

    await htmlFile.writeAsString(_buildAiAnalysisHtml(), encoding: utf8);
    await csvFile.writeAsString(_buildAiTtdCsv(), encoding: utf8);
    await jsonFile.writeAsString(
      const JsonEncoder.withIndent('  ').convert(_buildAiExportPayload()),
      encoding: utf8,
    );

    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text('Экспорт готов: ${htmlFile.path}'),
        duration: const Duration(seconds: 5),
      ),
    );
  } catch (e) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: Text('Не удалось экспортировать AI-анализ: $e')),
    );
  }
}

Directory _resolveExportDirectory() {
  final home = Platform.environment['HOME'] ?? Platform.environment['USERPROFILE'];
  if (home != null && home.trim().isNotEmpty) {
    final downloads = Directory('$home/Downloads');
    if (downloads.existsSync()) return downloads;
  }
  return Directory.systemTemp;
}

Map<String, dynamic> _buildAiExportPayload() {
  return {
    'match': {
      'match_id': widget.matchId,
      'video_id': widget.videoId,
      'title': widget.matchTitle,
      'team': widget.teamName,
      'exported_at': DateTime.now().toIso8601String(),
    },
    'teams': {
      'my_team': {
        'name': _myTeamConfig.displayName,
        'side': _sideTagToString(_myTeamConfig.sideTag),
        'color': _myTeamConfig.primaryColor.value,
      },
      'opponent': {
        'name': _opponentTeamConfig.displayName,
        'side': _sideTagToString(_opponentTeamConfig.sideTag),
        'color': _opponentTeamConfig.primaryColor.value,
      },
    },
    'summary': _aiTracking.aiSummary,
    'match_stats': _aiTracking.aiMatchStats,
    'events': _aiTracking.autoEvents.map((e) => {
          'type': e.type,
          'title': e.title,
          'subtitle': e.subtitle,
          'time_ms': e.timeMs,
          'confidence': e.confidence,
          'meta': e.meta,
        }).toList(),
    'ttd': _aiTracking.ttdSuggestions.map((e) => {
          'code': e.code,
          'title': e.title,
          'section': e.section,
          'time_ms': e.timeMs,
          'confidence': e.confidence,
          'success': e.success,
          'meta': e.meta,
        }).toList(),
    'players': _aiTracking.aiPlayerStats.map((e) => {
          'track_id': e.trackId,
          'team': e.team,
          'player_name': e.playerName,
          'touches': e.touches,
          'passes': e.passes,
          'successful_passes': e.successfulPasses,
          'shots': e.shots,
          'interceptions': e.interceptions,
          'distance_m': e.distanceM,
          'max_speed_kmh': e.maxSpeedKmh,
          'rating': e.rating,
        }).toList(),
    'report_rows': {
      'main': _mainReportRows,
      'passes': _passReportRows,
      'goalkeeper': _goalkeeperReportRows,
    },
    'coach_annotations': _coachAnnotations.map((e) => e.toJson()).toList(),
  };
}

String _csvCell(dynamic value) {
  final raw = (value ?? '').toString().replaceAll('"', '""');
  return '"$raw"';
}

String _formatExportTime(int ms) => _formatAiTime(ms);

String _buildAiTtdCsv() {
  final rows = <List<dynamic>>[
    ['Время', 'Раздел', 'Код', 'Название', 'Команда', 'Игрок/трек', 'Успешно', 'Уверенность', 'Описание'],
  ];

  for (final item in _aiTracking.ttdSuggestions) {
    final meta = item.meta ?? const <String, dynamic>{};
    final player = meta['player_name'] ?? meta['track_id'] ?? meta['player_id'] ?? '';
    rows.add([
      _formatExportTime(item.timeMs),
      item.section,
      item.code,
      item.title,
      meta['team'] ?? '',
      player,
      item.success ? 'Да' : 'Нет',
      '${(item.confidence * 100).round()}%',
      meta['description'] ?? '',
    ]);
  }

  rows.add([]);
  rows.add(['Сводная таблица ТТД']);
  rows.add(['Раздел', 'Показатель', 'Значение']);
  void addReport(String section, List<Map<String, dynamic>> source) {
    for (final row in source) {
      rows.add([
        section,
        row['title'] ?? row['label'] ?? row['name'] ?? row['code'] ?? '',
        row['value'] ?? row['count'] ?? row['total'] ?? '',
      ]);
    }
  }

  addReport('Основные действия', _mainReportRows);
  addReport('Передачи', _passReportRows);
  addReport('Вратарь', _goalkeeperReportRows);

  return rows.map((r) => r.map(_csvCell).join(';')).join('\n');
}

String _buildAiAnalysisHtml() {
  String esc(dynamic value) => const HtmlEscape().convert((value ?? '').toString());
  final events = _aiTracking.autoEvents;
  final ttd = _aiTracking.ttdSuggestions;
  final players = _aiTracking.aiPlayerStats;
  final goals = events.where((e) => e.type.contains('goal')).length;
  final cards = events.where((e) => e.type.contains('card')).length;
  final passes = ttd.where((e) => e.section == 'Передачи' || e.code.contains('pass')).length;
  final notes = (_aiTracking.aiSummary?['notes'] as List?)?.cast<dynamic>() ?? const [];

  String rowsForTtd() {
    if (ttd.isEmpty) {
      return '<tr><td colspan="8" class="muted">AI пока не вернул ТТД.</td></tr>';
    }
    return ttd.map((e) {
      final meta = e.meta ?? const <String, dynamic>{};
      return '<tr>'
          '<td>${esc(_formatExportTime(e.timeMs))}</td>'
          '<td>${esc(e.section)}</td>'
          '<td>${esc(e.code)}</td>'
          '<td><b>${esc(e.title)}</b><div class="muted">${esc(meta['description'] ?? '')}</div></td>'
          '<td>${esc(meta['team'] ?? '')}</td>'
          '<td>${esc(meta['track_id'] ?? meta['player_id'] ?? '')}</td>'
          '<td>${e.success ? 'Да' : 'Нет'}</td>'
          '<td>${(e.confidence * 100).round()}%</td>'
          '</tr>';
    }).join();
  }

  String rowsForPlayers() {
    if (players.isEmpty) {
      return '<tr><td colspan="9" class="muted">Статистика игроков появится после привязки треков.</td></tr>';
    }
    return players.map((p) => '<tr>'
        '<td>${esc(p.playerName)}</td>'
        '<td>${esc(p.team ?? '')}</td>'
        '<td>${p.touches}</td>'
        '<td>${p.passes}</td>'
        '<td>${p.successfulPasses}</td>'
        '<td>${p.shots}</td>'
        '<td>${p.interceptions}</td>'
        '<td>${p.distanceM.toStringAsFixed(0)} м</td>'
        '<td>${p.rating.toStringAsFixed(1)}</td>'
        '</tr>').join();
  }

  String rowsForEvents() {
    if (events.isEmpty) {
      return '<tr><td colspan="5" class="muted">События не найдены.</td></tr>';
    }
    return events.map((e) => '<tr>'
        '<td>${esc(_formatExportTime(e.timeMs))}</td>'
        '<td>${esc(e.type)}</td>'
        '<td><b>${esc(e.title)}</b><div class="muted">${esc(e.subtitle)}</div></td>'
        '<td>${esc(e.meta?['team'] ?? '')}</td>'
        '<td>${(e.confidence * 100).round()}%</td>'
        '</tr>').join();
  }

  String noteRows() {
    if (notes.isEmpty) {
      return '<li>AI заметки сохранены как отдельный блок. DeepSeek можно подключить следующим этапом.</li>';
    }
    return notes.map((n) => '<li>${esc(n)}</li>').join();
  }

  return '''
<!doctype html>
<html lang="ru">
