<style>
body{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;background:#f5f7f6;color:#111827;margin:0;padding:32px;}
.header{background:#111827;color:white;border-radius:28px;padding:28px;margin-bottom:18px;display:flex;justify-content:space-between;gap:20px;align-items:flex-start;}
.logo{font-size:24px;font-weight:900;letter-spacing:-.04em}.sub{opacity:.75;margin-top:6px}.badge{display:inline-flex;padding:8px 12px;border-radius:999px;background:#00A750;color:white;font-weight:800;font-size:12px;margin-top:12px;}
.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:18px 0}.card{background:white;border-radius:22px;padding:18px;box-shadow:0 16px 44px rgba(16,24,40,.08);}.k{font-size:28px;font-weight:900}.l{font-size:12px;color:#667085;text-transform:uppercase;font-weight:800;letter-spacing:.08em}h2{margin:28px 0 12px;font-size:20px}.team{display:flex;gap:10px;align-items:center}.dot{width:14px;height:14px;border-radius:999px;display:inline-block}.muted{color:#667085;font-size:12px}table{width:100%;border-collapse:separate;border-spacing:0 8px}th{text-align:left;font-size:11px;color:#667085;text-transform:uppercase;letter-spacing:.06em;padding:0 12px}td{background:white;padding:13px 12px;border-top:1px solid #eef2f7;border-bottom:1px solid #eef2f7}td:first-child{border-radius:14px 0 0 14px;border-left:1px solid #eef2f7}td:last-child{border-radius:0 14px 14px 0;border-right:1px solid #eef2f7}.notes{background:white;border-radius:22px;padding:18px;box-shadow:0 16px 44px rgba(16,24,40,.08)}
