Future<void> _confirmTopAiSuggestions() async {
  final suggestions = _aiTracking.ttdSuggestions
      .where((e) => e.confidence >= 0.75)
      .take(20)
      .toList();

  if (suggestions.isEmpty) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(content: Text('Нет уверенных AI-подсказок')),
    );
    return;
  }

  for (final s in suggestions) {
    await _confirmAiSuggestion(s);
  }

  if (!mounted) return;
  ScaffoldMessenger.of(context).showSnackBar(
    SnackBar(content: Text('Подтверждено ${suggestions.length} AI-действий')),
  );
}

List<TacticalAnnotation> _copyCoachAnnotations() =>
    _coachAnnotations.map((e) => TacticalAnnotation.fromJson(e.toJson())).toList();

void _pushCoachUndo() {
  _coachUndoStack.add(_copyCoachAnnotations());
  if (_coachUndoStack.length > 24) {
    _coachUndoStack.removeAt(0);
  }
}

