Offset _normalizeCoachPoint(Offset local, Size size) {
  final dx = size.width == 0 ? 0.0 : (local.dx / size.width).clamp(0.0, 1.0).toDouble();
  final dy = size.height == 0 ? 0.0 : (local.dy / size.height).clamp(0.0, 1.0).toDouble();
  return Offset(dx, dy);
}

String _coachAnnotationId() => 'coach_${DateTime.now().microsecondsSinceEpoch}_${_coachAnnotations.length}';

int _coachAnnotationHitTest(Offset point) {
  if (_coachAnnotations.isEmpty) return -1;
  const threshold = 0.035;

  double distanceToSegment(Offset p, Offset a, Offset b) {
    final vx = b.dx - a.dx;
    final vy = b.dy - a.dy;
    final wx = p.dx - a.dx;
    final wy = p.dy - a.dy;
    final len2 = vx * vx + vy * vy;
    if (len2 <= 0) return (p - a).distance;
    final t = ((wx * vx + wy * vy) / len2).clamp(0.0, 1.0).toDouble();
    final projection = Offset(a.dx + t * vx, a.dy + t * vy);
    return (p - projection).distance;
  }

  for (int i = _coachAnnotations.length - 1; i >= 0; i--) {
    final item = _coachAnnotations[i];
    if (item.start != null && (point - item.start!).distance <= threshold) return i;
    if (item.textOffset != null && (point - item.textOffset!).distance <= threshold) return i;
    if (item.start != null && item.end != null) {
      final a = item.start!;
      final b = item.end!;
      if (distanceToSegment(point, a, b) <= threshold) return i;
      final minX = math.min(a.dx, b.dx) - threshold;
      final maxX = math.max(a.dx, b.dx) + threshold;
      final minY = math.min(a.dy, b.dy) - threshold;
      final maxY = math.max(a.dy, b.dy) + threshold;
      if ((item.type == TacticalToolType.rect || item.type == TacticalToolType.zone || item.type == TacticalToolType.circle) &&
          point.dx >= minX && point.dx <= maxX && point.dy >= minY && point.dy <= maxY) {
        return i;
      }
    }
    final points = item.points;
    if (points != null && points.isNotEmpty) {
      for (int j = 1; j < points.length; j++) {
        if (distanceToSegment(point, points[j - 1], points[j]) <= threshold) return i;
      }
    }
  }
  return -1;
}

void _handleCoachTapDown(TapDownDetails details, Size size) {
  if (!_coachBoardEnabled) return;
  final p = _normalizeCoachPoint(details.localPosition, size);
  if (_coachTool == TacticalToolType.eraser) {
    final index = _coachAnnotationHitTest(p);
    if (index < 0) return;
    _pushCoachUndo();
    setState(() => _coachAnnotations.removeAt(index));
    return;
  }

  if (_coachTool == TacticalToolType.playerMarker || _coachTool == TacticalToolType.text) {
    _pushCoachUndo();
    final item = TacticalAnnotation(
      id: _coachAnnotationId(),
      type: _coachTool,
      color: _coachDrawColor,
      strokeWidth: _coachStrokeWidth,
      start: p,
      textOffset: p,
      text: _coachTool == TacticalToolType.text ? 'Заметка' : 'T',
      fontSize: 18,
    );
    setState(() => _coachAnnotations.add(item));
  }
}

void _handleCoachPanStart(DragStartDetails details, Size size) {
  if (!_coachBoardEnabled) return;
  if (_coachTool == TacticalToolType.playerMarker ||
      _coachTool == TacticalToolType.text ||
      _coachTool == TacticalToolType.eraser ||
      _coachTool == TacticalToolType.select) {
    return;
  }

  final p = _normalizeCoachPoint(details.localPosition, size);
  final lineStyle = _coachTool == TacticalToolType.dashedLine
      ? TacticalLineStyle.dashed
      : TacticalLineStyle.solid;

  setState(() {
    _coachDraftAnnotation = TacticalAnnotation(
      id: _coachAnnotationId(),
      type: _coachTool,
      color: _coachDrawColor,
      strokeWidth: _coachStrokeWidth,
      lineStyle: lineStyle,
      start: p,
      end: p,
      points: _coachTool == TacticalToolType.freeDraw ? <Offset>[p] : null,
      filled: _coachTool == TacticalToolType.zone,
    );
  });
}

void _handleCoachPanUpdate(DragUpdateDetails details, Size size) {
  if (!_coachBoardEnabled || _coachDraftAnnotation == null) return;
  final p = _normalizeCoachPoint(details.localPosition, size);
  final draft = _coachDraftAnnotation!;
  setState(() {
    if (draft.type == TacticalToolType.freeDraw) {
      final points = <Offset>[...(draft.points ?? const <Offset>[]), p];
      _coachDraftAnnotation = draft.copyWith(points: points, end: p);
    } else {
      _coachDraftAnnotation = draft.copyWith(end: p);
    }
  });
}

void _handleCoachPanEnd(DragEndDetails details) {
  if (!_coachBoardEnabled || _coachDraftAnnotation == null) return;
  final draft = _coachDraftAnnotation!;
  _pushCoachUndo();
  setState(() {
    _coachAnnotations.add(draft);
    _coachDraftAnnotation = null;
  });
}

void _undoCoachAnnotation() {
  if (_coachUndoStack.isEmpty) return;
  final previous = _coachUndoStack.removeLast();
  setState(() {
    _coachAnnotations
      ..clear()
      ..addAll(previous);
    _coachDraftAnnotation = null;
  });
}

void _clearCoachAnnotations() {
  if (_coachAnnotations.isEmpty) return;
  _pushCoachUndo();
  setState(() {
    _coachAnnotations.clear();
    _coachDraftAnnotation = null;
  });
}
  
