}




void _onAiServerControllerChanged() {
  if (!mounted || _isApplyingServerFramePacket) return;

  final packet = _aiServerController.currentFramePacket;
  if (packet == null) return;

  final signature = Object.hash(
    packet.jobId,
    packet.timeMs,
    packet.tracks.length,
    packet.tracks.map((e) => e.trackId).join(','),
  );

  if (signature == _lastAppliedServerFrameSignature) return;
  _lastAppliedServerFrameSignature = signature;

  _applyServerPacketToOverlay(packet);

  if (!mounted) return;
  setState(() {
    _isLoadingServerFrame = false;
    if (packet.tracks.isNotEmpty) {
      _aiStatusText =
          'AI кадр ${Formatters.formatDuration(Duration(milliseconds: packet.timeMs))}: ${packet.tracks.length} игроков';
    }
  });
}

void _applyServerPacketToOverlay(AiFramePacket packet) {
  if (!mounted) return;
  debugPrint('APPLY PACKET: ${packet.tracks.length} tracks, time=${packet.timeMs}');

  final mappedTracks = mapServerTracksToPlayerTracks(packet.tracks);
  final frameTimeMs = packet.timeMs;

  if (mappedTracks.isEmpty) {
    debugPrint(
      'MAPPED TRACKS: 0 — keeping previous overlay, frame may still be processing',
    );
    _lastServerAiPacketTimeMs = frameTimeMs;
    if (mounted) {
      setState(() {
        _isLoadingServerFrame = false;
        _aiStatusText = 'AI кадр ещё обрабатывается — показываю последний доступный трек';
      });
    }
    return;
  }

  if (mappedTracks.isNotEmpty) {
    final first = mappedTracks.first;
    final p = first.points.isNotEmpty ? first.points.last.position : first.currentPosition;
    debugPrint(
      'MAPPED TRACKS: ${mappedTracks.length}; first=${first.id} '
      'point=${p?.dx.toStringAsFixed(1)},${p?.dy.toStringAsFixed(1)} '
      'box=${first.currentBoundingBox}',
    );
  } else {
    debugPrint('MAPPED TRACKS: 0');
  }

  _isApplyingServerFramePacket = true;
  _lastServerAiPacketTimeMs = frameTimeMs;

  final liveTracks = <PlayerTrack>[];
  final visibleIds = <String>{};

  for (final rawTrack in mappedTracks) {
    visibleIds.add(rawTrack.id);
    final normalized = _buildLiveServerTrack(rawTrack, frameTimeMs);
    liveTracks.add(normalized);
    _serverAiLastTracks[normalized.id] = normalized;
  }

  // Не держим на экране треки, которых сервер давно не видит, но историю
  // оставляем короткой, чтобы тепловая карта и trail не обнулялись каждую секунду.
  // Не удаляем игрока мгновенно, если на одном кадре сервер его потерял:
  // в футбольном видео бывают перекрытия, камера и дальний план. Держим
  // последний bbox короткое время, чтобы квадраты не моргали и не пропадали.
  _serverAiLastTracks.removeWhere(
    (id, track) => frameTimeMs - track.lastSeenTimeMs > 1600,
  );

  final stabilizedTracks = <PlayerTrack>[
    ..._serverAiLastTracks.values,
  ];

  _aiTracking.tracks = stabilizedTracks;

  if (stabilizedTracks.isNotEmpty) {
    final selectedId = _aiTracking.selectedTrackId;
    PlayerTrack selected = stabilizedTracks.first;

    if (selectedId != null) {
      final match = stabilizedTracks.where((e) => e.id == selectedId).toList();
      if (match.isNotEmpty) selected = match.first;
    }

    _aiTracking.lockedTrack = selected;
    _aiTracking.selectedTrackId = selected.id;
    _aiTracking.selectedTrack = selected;
    _aiTracking.lockedRect = selected.currentBoundingBox;
    _aiTracking.lockedPosition = selected.currentPosition;
    _aiTracking.isLocked = true;
    _aiTracking._recalculateLiveStats(selected);
  } else {
    _aiTracking.lockedTrack = null;
    _aiTracking.selectedTrack = null;
    _aiTracking.selectedTrackId = null;
    _aiTracking.lockedRect = null;
    _aiTracking.lockedPosition = null;
    _aiTracking.isLocked = false;
  }

  _aiTracking.notifyListeners();
  if (mounted) setState(() => _isLoadingServerFrame = false);
  _isApplyingServerFramePacket = false;
}

PlayerTrack _buildLiveServerTrack(PlayerTrack rawTrack, int frameTimeMs) {
  final sourceSize = _analysisFrameSize();
  final normalizedRect = _normalizeServerRectToAnalysisSpace(
    rawTrack.currentBoundingBox,
    sourceSize,
  );
  final normalizedPosition = _normalizeServerPointToAnalysisSpace(
    rawTrack.currentPosition ??
        (rawTrack.points.isNotEmpty ? rawTrack.points.last.position : Offset.zero),
    sourceSize,
    normalizedRect,
  );

  final rawPoint = rawTrack.points.isNotEmpty
      ? TrackPoint(
          position: normalizedPosition,
          timeMs: frameTimeMs,
          speed: rawTrack.points.last.speed,
          vx: rawTrack.points.last.vx,
          vy: rawTrack.points.last.vy,
          ax: rawTrack.points.last.ax,
          ay: rawTrack.points.last.ay,
          rect: normalizedRect,
        )
      : TrackPoint(
          position: normalizedPosition,
          timeMs: frameTimeMs,
          speed: rawTrack.speed ?? 0,
          rect: normalizedRect,
        );

  final history = List<TrackPoint>.from(
    _serverAiTrackHistory[rawTrack.id] ?? const <TrackPoint>[],
  );

  final prev = history.isNotEmpty ? history.last : null;
  final motion = _buildServerMotion(prev, rawPoint, frameTimeMs, rawTrack.speed);

  final livePoint = TrackPoint(
    position: rawPoint.position,
    timeMs: frameTimeMs,
    speed: motion.speedKmh,
    vx: motion.vx,
    vy: motion.vy,
    ax: motion.ax,
    ay: motion.ay,
    rect: rawPoint.rect ?? rawTrack.currentBoundingBox,
  );

  if (history.isEmpty) {
    history.add(livePoint);
  } else if ((frameTimeMs - history.last.timeMs).abs() <= 35) {
    history[history.length - 1] = livePoint;
  } else if (frameTimeMs > history.last.timeMs) {
    history.add(livePoint);
  } else {
    // При перемотке назад строим историю заново от текущего кадра,
    // чтобы trail не тянулся из будущего.
    history
      ..clear()
      ..add(livePoint);
  }

  final trimmedHistory = history.length > 140
      ? history.sublist(history.length - 140)
      : history;

  _serverAiTrackHistory[rawTrack.id] = trimmedHistory;

  return rawTrack.copyWith(
    points: trimmedHistory,
    speed: motion.speedKmh,
    createdAtMs: trimmedHistory.first.timeMs,
    lastSeenTimeMs: frameTimeMs,
    lockedBox: livePoint.rect ?? normalizedRect ?? rawTrack.currentBoundingBox,
  );
}

Offset _normalizeServerPointToAnalysisSpace(
  Offset point,
  Size sourceSize,
  Rect? rect,
) {
  // Если bbox есть, нижний центр bbox точнее для игрока на видео.
  if (rect != null) {
    return Offset(rect.center.dx, rect.bottom);
  }

  if (point == Offset.zero) return point;

  // Нормализованные координаты 0..1.
  if (point.dx >= 0 && point.dx <= 1.5 && point.dy >= 0 && point.dy <= 1.5) {
    return Offset(point.dx * sourceSize.width, point.dy * sourceSize.height);
  }

  // Координаты из нативного кадра видео, например 1920x1080, приводим
  // к analysis-space 640x360/по аспекту.
  if (_controller.value.isInitialized) {
    final native = _controller.value.size;
    if (native.width > 0 && native.height > 0) {
      final looksLikeNative =
          point.dx <= native.width * 1.25 && point.dy <= native.height * 1.25 &&
          (point.dx > sourceSize.width * 1.15 || point.dy > sourceSize.height * 1.15);
      if (looksLikeNative) {
        return Offset(
          point.dx * sourceSize.width / native.width,
          point.dy * sourceSize.height / native.height,
        );
      }
    }
  }

  return Offset(
    point.dx.clamp(0.0, sourceSize.width).toDouble(),
    point.dy.clamp(0.0, sourceSize.height).toDouble(),
  );
}

Rect? _normalizeServerRectToAnalysisSpace(Rect? rect, Size sourceSize) {
  if (rect == null) return null;

  var r = rect;

  // Нормализованный bbox 0..1.
  if (r.right <= 1.5 && r.bottom <= 1.5 && r.left >= 0 && r.top >= 0) {
    r = Rect.fromLTRB(
      r.left * sourceSize.width,
      r.top * sourceSize.height,
      r.right * sourceSize.width,
      r.bottom * sourceSize.height,
    );
  } else if (_controller.value.isInitialized) {
    final native = _controller.value.size;
    final looksLikeNative = native.width > 0 &&
        native.height > 0 &&
        r.right <= native.width * 1.25 &&
        r.bottom <= native.height * 1.25 &&
        (r.right > sourceSize.width * 1.15 || r.bottom > sourceSize.height * 1.15);

    if (looksLikeNative) {
      r = Rect.fromLTRB(
        r.left * sourceSize.width / native.width,
        r.top * sourceSize.height / native.height,
        r.right * sourceSize.width / native.width,
        r.bottom * sourceSize.height / native.height,
      );
    }
  }

  return Rect.fromLTRB(
    r.left.clamp(0.0, sourceSize.width).toDouble(),
    r.top.clamp(0.0, sourceSize.height).toDouble(),
    r.right.clamp(0.0, sourceSize.width).toDouble(),
    r.bottom.clamp(0.0, sourceSize.height).toDouble(),
  );
}

TrackMotionResult _buildServerMotion(
  TrackPoint? prev,
  TrackPoint current,
  int frameTimeMs,
  double? serverSpeed,
) {
  if (prev == null) {
    return TrackMotionResult(
      speedKmh: (serverSpeed ?? current.speed).clamp(0.0, 42.0).toDouble(),
      vx: 0,
      vy: 0,
      ax: 0,
      ay: 0,
    );
  }

  final dt = ((frameTimeMs - prev.timeMs) / 1000.0).clamp(0.04, 3.0).toDouble();
  final dx = current.position.dx - prev.position.dx;
  final dy = current.position.dy - prev.position.dy;
  final vx = dx / dt;
  final vy = dy / dt;
  final ax = (vx - prev.vx) / dt;
  final ay = (vy - prev.vy) / dt;

  final distPx = math.sqrt(dx * dx + dy * dy);
  final meters = distPx * _estimateMetersPerPixel(current.position.dy);
  final calculatedSpeed = (meters / dt) * 3.6;

  final rawSpeed = (serverSpeed != null && serverSpeed > 0)
      ? serverSpeed
      : calculatedSpeed;

  // Для LIVE не сглаживаем скорость слишком сильно: старое значение 0.38
  // визуально тормозило движение и долго держало 0.0 км/ч.
  final smoothedSpeed = prev.speed + (rawSpeed - prev.speed) * 0.72;

  return TrackMotionResult(
    speedKmh: smoothedSpeed.clamp(0.0, 42.0).toDouble(),
    vx: vx,
    vy: vy,
    ax: ax,
    ay: ay,
  );
}

double _estimateMetersPerPixel(double y) {
  // Приблизительная перспектива футбольного кадра: дальняя часть поля
  // даёт больше метров на пиксель, ближняя — меньше. Этого достаточно,
  // чтобы LIVE-скорость перестала быть постоянно 0.0 и не улетала в сотни.
  final h = _analysisFrameSize().height;
  final normalizedY = (h <= 0 ? 0.5 : (y / h).clamp(0.0, 1.0)).toDouble();
  final farScale = 0.052;
  final nearScale = 0.020;
  return (farScale + (nearScale - farScale) * normalizedY).toDouble();
}
     
    Widget _buildRailButton({
