  Widget _buildReviewVideoSurface({
  bool showActionRail = true,
  bool showInnerHeader = true,
  bool showInternalTimeline = true,
}) {
  final bool panelOpen = _activeOverlayPanel != ReviewOverlayPanel.none;

  return Container(
    color: ReviewUiPalette.bg,
    child: Padding(
      padding: EdgeInsets.all(_isVideoFullscreen ? 0 : 6),
      child: LayoutBuilder(
        builder: (context, constraints) {
          final totalWidth = constraints.maxWidth;
          final railWidth = showActionRail ? _adaptiveRailWidth(totalWidth) : 0.0;
          final panelWidth = panelOpen ? _adaptivePanelWidth(totalWidth) : 0.0;
          final gap = _isVideoFullscreen ? 0.0 : _adaptiveGap(totalWidth);
          final railGap = showActionRail ? gap : 0.0;
          final videoWidth = totalWidth -
              railWidth -
              railGap -
              (panelOpen ? panelWidth + gap : 0);

          final rail = SizedBox(
            width: railWidth,
            child: _buildRightMainRail(),
          );

          final panel = SizedBox(
            width: panelWidth,
            child: _buildCenterSlidingPanel(),
          );

          final video = SizedBox(
            width: videoWidth.clamp(260.0, totalWidth).toDouble(),
            child: Container(
              decoration: BoxDecoration(
                color: ReviewUiPalette.panel,
                borderRadius: BorderRadius.circular(_isVideoFullscreen ? 0 : 14),
                border: Border.all(
                  color: _isVideoFullscreen ? Colors.transparent : ReviewUiPalette.line,
                  width: 1,
                ),
                boxShadow: _isVideoFullscreen
                    ? const []
                    : [
                        BoxShadow(
                          color: Colors.black.withOpacity(0.035),
                          blurRadius: 18,
                          offset: const Offset(0, 10),
                        ),
                      ],
              ),
              child: ClipRRect(
                borderRadius: BorderRadius.circular(_isVideoFullscreen ? 0 : 14),
                child: Column(
                  children: [
                    if (!_isVideoFullscreen && showInnerHeader) _buildReviewWorkspaceHeader(),
                    if (showInternalTimeline && _effectiveInternalVideoControls)
                      Padding(
                        padding: EdgeInsets.fromLTRB(
                          6,
                          _isVideoFullscreen ? 0 : 0,
                          6,
                          6,
                        ),
                        child: _buildTopVideoTimelineBar(),
                      ),
                    Expanded(
                      child: Padding(
                        padding: EdgeInsets.fromLTRB(
                          _isVideoFullscreen ? 0 : 6,
                          _effectiveInternalVideoControls || !_isVideoFullscreen ? 0 : 6,
                          _isVideoFullscreen ? 0 : 6,
                          _isVideoFullscreen ? 0 : 6,
                        ),
                        child: ClipRRect(
                          borderRadius: BorderRadius.circular(_isVideoFullscreen ? 0 : 12),
                          child: Container(
                            color: Colors.black,
                            child: Stack(
                              fit: StackFit.expand,
                              children: [
                                _buildVideoSection(),
                                _buildSelectedPlayerOverlayCard(),
                                _buildSelectedEpisodeOverlayBadge(),
                                _buildBottomPlayersStrip(),
                              ],
                            ),
                          ),
                        ),
                      ),
                    ),
                  ],
                ),
              ),
            ),
          );

          return Row(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              if (showActionRail && widget.railOnLeft) ...[
                rail,
                SizedBox(width: gap),
              ],
              video,
              if (panelOpen) ...[
                SizedBox(width: gap),
                panel,
              ],
              if (showActionRail && !widget.railOnLeft) ...[
                SizedBox(width: gap),
                rail,
              ],
            ],
          );
        },
      ),
    ),
  );
}

