}

  Map<String, dynamic> _decode(http.Response resp) {
    return Formatters.decodeResponse(resp);
  }

  String _s(dynamic v) => Formatters.safeString(v);
  int _i(dynamic v) => Formatters.safeInt(v);

  static const String _matchInfoUpdateUrl = 'https://sportotekaapp.ru/api/update_team_match_info.php';
  static const String _matchDeleteUrl = 'https://sportotekaapp.ru/api/delete_team_match.php';

