  Future<void> _renameCurrentMatch() async {
    final controller = TextEditingController(text: _displayMatchTitle);

    final newTitle = await Get.dialog<String>(
      AlertDialog(
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(18)),
        title: const Text(
          'Переименовать матч',
          style: TextStyle(fontWeight: FontWeight.w900),
        ),
        content: TextField(
          controller: controller,
          autofocus: true,
          textInputAction: TextInputAction.done,
          decoration: const InputDecoration(
            labelText: 'Название матча',
            hintText: 'Например: Гомель U13 — Минск U13',
          ),
          onSubmitted: (value) => Get.back(result: value.trim()),
        ),
        actions: [
          TextButton(
            onPressed: () => Get.back(),
            child: const Text('Отмена'),
          ),
          ElevatedButton(
            onPressed: () => Get.back(result: controller.text.trim()),
            style: ElevatedButton.styleFrom(
              backgroundColor: const Color(0xFF28A86B),
              foregroundColor: Colors.white,
            ),
            child: const Text('Сохранить'),
          ),
        ],
      ),
    );

    controller.dispose();

    if (newTitle == null) return;
    final cleanTitle = newTitle.trim();
    if (cleanTitle.isEmpty) {
      Get.snackbar('Ошибка', 'Введите название матча');
      return;
    }

    Get.dialog(
      const Center(child: CircularProgressIndicator()),
      barrierDismissible: false,
    );

    try {
      final response = await http
          .post(
            Uri.parse(_matchInfoUpdateUrl),
            headers: const {'Content-Type': 'application/json; charset=utf-8'},
            body: jsonEncode({
              'match_id': widget.matchId,
              'id': widget.matchId,
              'team_id': widget.teamId,
              'title': cleanTitle,
              'match_title': cleanTitle,
            }),
          )
          .timeout(const Duration(seconds: 20));

      final data = _decode(response);

      if (Get.isDialogOpen ?? false) Get.back();

      final ok = data['success'] == true || data['status'] == 'success';
      if (ok) {
        if (mounted) {
          setState(() => _currentMatchTitle = cleanTitle);
        }
        Get.snackbar('Готово', 'Название матча обновлено');
      } else {
        Get.snackbar(
          'Ошибка',
          _s(data['message']).isNotEmpty ? _s(data['message']) : 'Не удалось переименовать матч',
        );
      }
    } catch (e) {
      if (Get.isDialogOpen ?? false) Get.back();
      Get.snackbar('Ошибка', 'Ошибка переименования матча: $e');
    }
  }

  Future<void> _deleteCurrentMatch() async {
    final confirmed = await Get.dialog<bool>(
      AlertDialog(
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(18)),
        title: const Text(
          'Удалить матч?',
          style: TextStyle(fontWeight: FontWeight.w900),
        ),
        content: Text(
          'Матч\n\n$_displayMatchTitle\n\nбудет удалён из раздела видео полностью.',
        ),
        actions: [
          TextButton(
            onPressed: () => Get.back(result: false),
            child: const Text('Отмена'),
          ),
          ElevatedButton(
            onPressed: () => Get.back(result: true),
            style: ElevatedButton.styleFrom(
              backgroundColor: Colors.red,
              foregroundColor: Colors.white,
            ),
            child: const Text('Удалить'),
          ),
        ],
      ),
    );

    if (confirmed != true) return;

    Get.dialog(
      const Center(child: CircularProgressIndicator()),
      barrierDismissible: false,
    );

    try {
      final response = await http
          .post(
            Uri.parse(_matchDeleteUrl),
            headers: const {'Content-Type': 'application/json; charset=utf-8'},
            body: jsonEncode({
              'id': widget.matchId,
              'match_id': widget.matchId,
              'team_id': widget.teamId,
            }),
          )
          .timeout(const Duration(seconds: 20));

      final data = _decode(response);

      if (Get.isDialogOpen ?? false) Get.back();

      final ok = data['success'] == true || data['status'] == 'success';
      if (ok) {
        Get.snackbar('Готово', 'Матч удалён');
        if (!mounted) return;
        Get.back(result: {'deleted': true, 'match_id': widget.matchId});
      } else {
        Get.snackbar(
          'Ошибка',
          _s(data['message']).isNotEmpty ? _s(data['message']) : 'Не удалось удалить матч',
        );
      }
    } catch (e) {
      if (Get.isDialogOpen ?? false) Get.back();
      Get.snackbar('Ошибка', 'Ошибка удаления матча: $e');
    }
  }

  String _playerFirstName(Map<String, dynamic> p) => PlayerHelpers.firstName(p);
  String _playerLastName(Map<String, dynamic> p) => PlayerHelpers.lastName(p);
