Future<void> _openTeamIdentitySheet() async {
  await showCmrAiWindow<void>(
    context: context,
    title: 'Цвета команд для AI',
    subtitle: 'Настройка формы для трекинга, heatmap и отчёта',
    maxWidth: 920,
    child: TeamIdentitySetupSheet(
      myTeamConfig: _myTeamConfig,
      opponentTeamConfig: _opponentTeamConfig,
      onApply: (myCfg, oppCfg) {
