Widget _buildVideoSection() {
  if (!_videoReady) {
    return const Center(
      child: CircularProgressIndicator(),
    );
  }

  return Stack(
    fit: StackFit.expand,
    children: [
      FittedBox(
        fit: BoxFit.contain,
        child: SizedBox(
          width: _controller.value.size.width,
          height: _controller.value.size.height,
          child: VideoPlayer(_controller),
        ),
      ),
      Positioned.fill(
        child: LayoutBuilder(
          builder: (context, constraints) {
            final overlaySize = Size(
              constraints.maxWidth,
              constraints.maxHeight,
            );

            return GestureDetector(
              behavior: HitTestBehavior.opaque,
              onTapUp: (details) async {
                _showOverlay();
                _showTapPointMarker(details.localPosition);

                final mappedTap = _mapTapToAnalysisSpace(
                  localPosition: details.localPosition,
                  sourceSize: _analysisFrameSize(),
                  overlaySize: overlaySize,
                  fit: BoxFit.contain,
                );

              
                if (_useServerAi) {
                  return;
                }

                await _warmupDetections();
                _aiTracking.selectTrackByTap(mappedTap);

                if (_aiTracking.isLocked && !_aiTracking.isRunning) {
                  _startAiLoopDirectly(
                    overlaySize: overlaySize,
                    fit: BoxFit.contain,
                  );
                }
              },
              child: CustomPaint(
                painter: PlayerTrackingPainter(
                  controller: _aiTracking,
                  currentTimeMs: _controller.value.position.inMilliseconds,
                  fieldSize: overlaySize,
                  sourceSize: _analysisFrameSize(),
                  fit: BoxFit.contain,
                ),
              ),
            );
          },
        ),
      ),
      if (_showHeatmap && _aiTracking.selectedTrack != null)
        Positioned.fill(
          child: CustomPaint(
            painter: TrackingHeatmapPainter(
              points: _aiTracking.selectedTrack!.points,
              color: _aiTracking.selectedTrack!.color,
            ),
          ),
        ),
      _buildCoachDrawingLayer(),
      _buildTapMarkerOverlay(),
      _buildPossessionBadge(),
      _buildPassNetworkBadge(),
    ],
  );
}

Widget _buildCoachDrawingLayer() {
  if (!_coachBoardEnabled && _coachAnnotations.isEmpty) {
    return const SizedBox.shrink();
  }

  return Positioned.fill(
    child: LayoutBuilder(
      builder: (context, constraints) {
        final size = Size(constraints.maxWidth, constraints.maxHeight);
        final items = <TacticalAnnotation>[
          ..._coachAnnotations,
          if (_coachDraftAnnotation != null) _coachDraftAnnotation!,
        ];

        final paintLayer = CustomPaint(
          painter: TacticalAnnotationPainter(items: items),
          child: const SizedBox.expand(),
        );

        return Stack(
          children: [
            GestureDetector(
              behavior: _coachBoardEnabled
                  ? HitTestBehavior.opaque
                  : HitTestBehavior.translucent,
              onTapDown: _coachBoardEnabled
                  ? (details) => _handleCoachTapDown(details, size)
                  : null,
              onPanStart: _coachBoardEnabled
                  ? (details) => _handleCoachPanStart(details, size)
                  : null,
              onPanUpdate: _coachBoardEnabled
                  ? (details) => _handleCoachPanUpdate(details, size)
                  : null,
              onPanEnd: _coachBoardEnabled ? _handleCoachPanEnd : null,
              child: paintLayer,
            ),
            if (_coachBoardEnabled)
              Positioned(
                left: 14,
                right: 14,
                top: 14,
                child: _buildCoachBoardToolbar(),
              ),
          ],
        );
      },
    ),
  );
}

