    @override
  Widget build(BuildContext context) {
    final isLandscape =
        MediaQuery.of(context).orientation == Orientation.landscape;

    Widget loadingBody() {
      return const ColoredBox(
        color: Color(0xFFF4F7FA),
        child: Center(
          child: CircularProgressIndicator(),
        ),
      );
    }

    Widget reviewBody() {
      // Верхний CMR chrome сам содержит SafeArea, поэтому здесь не добавляем
      // второй отступ сверху — иначе на macOS/iPad появляется лишняя высота.
      return _buildVideoCanvas();
    }

    Widget withTypography(Widget child) => DefaultTextStyle(
          style: AppTypography.custom(
            size: 12,
            weight: FontWeight.w400,
            color: ReviewUiPalette.text,
            height: 1.24,
            letterSpacing: 0,
          ),
          child: child,
        );

    if (_loading) {
      final body = loadingBody();
      if (widget.embedded) return withTypography(body);

      return withTypography(
        const Scaffold(
          backgroundColor: Colors.white,
          body: Center(
            child: CircularProgressIndicator(),
          ),
        ),
      );
    }

    if (widget.embedded) {
      return withTypography(
        Container(
          color: Colors.white,
          child: reviewBody(),
        ),
      );
    }

    return withTypography(
      Scaffold(
        backgroundColor: Colors.white,
        body: isLandscape ? reviewBody() : _buildFallbackPortrait(),
      ),
    );
  }
}



